window.CFA_DATA={"meta": {"title": "CFA PASS SYSTEM", "level": "Level I", "curriculumYear": 2027, "status": "Verified curriculum map; original study content is being expanded", "officialOutline": "2027 Level I Topic Outlines", "examFormat": "180 multiple-choice questions; two 135-minute sessions; three choices per question", "edition": "V5 FSA Core Course — Part 1", "questionCount": 274, "accuracyNote": "Official structure is verified; guides and questions are original and independently written.", "features": ["Search", "Confidence tracking", "Adaptive review", "Timed sessions", "Why each answer is correct", "Offline progress backup"], "completedFsaModules": 5}, "topics": [{"id": "quant", "name": "Quantitative Methods", "weight": "6–9%", "modules": [{"title": "Returns of Financial Assets and Instruments", "los": ["describe, compare, and interpret returns", "describe, compare, and interpret required rates of return, risk-free rates, risk premia, and inflation"]}, {"title": "Types of Financial Returns", "los": ["calculate, compare, and interpret different types of returns for financial assets, instruments, and indicators"]}, {"title": "Benchmarking Returns", "los": ["calculate and compare money-weighted and time-weighted rates of return", "describe the choices and the implications of the different weighting methods used in index construction and management, and calculate, interpret, and explain the value and the returns of an index"]}, {"title": "The Time Value of Money in Finance", "los": ["calculate and interpret the present value of fixed-income and equity instruments based on expected future cash flows Quantitative Methods", "calculate and interpret the implied return of fixed-income instruments and required return and implied growth of equity instruments given their present value and cash flows", "explain the cash flow additivity principle and its importance for the condition of no arbitrage, and explain its use in calculating implied forward interest rates, forward exchange rates, and option values"]}, {"title": "Statistical Characteristics of Asset Returns", "los": ["calculate, interpret, and evaluate various measures of (1) central tendency and location and (2) dispersion", "describe, interpret, and evaluate measures of skewness and kurtosis", "calculate, interpret, and evaluate covariance and correlation", "calculate, interpret, and evaluate semi-deviation and coefficient of variation"]}, {"title": "Statistical Distributions for Financial Asset Prices and Returns", "los": ["calculate, interpret, and evaluate unconditional expected values for mean, variance, and covariance", "calculate, interpret, and evaluate the principal moments of key statistical distributions used in finance", "calculate, interpret, and evaluate conditional expectations, variances, and covariances", "formulate investment problems through Bayesian updating"]}, {"title": "Estimation and Hypothesis Testing", "los": ["explain the central limit theorem and the application of confidence intervals and sampling methodologies", "explain hypothesis testing and its components, including statistical significance, Type I and Type II errors, and the power of a test; construct appropriate hypothesis tests; and interpret the results", "compare and contrast parametric and non-parametric tests, describe situations in which each is the more appropriate type of test, construct appropriate hypothesis tests, and interpret the results"]}, {"title": "The Return and Risk of a Financial Portfolio", "los": ["calculate, interpret, and evaluate the expected return, variance, standard deviation, covariance, and correlation of portfolio returns", "describe, calculate, and interpret the minimum-variance portfolio and portfolios that lie on the efficient frontier", "explain the selection of an optimal portfolio, given an investor’s risk aversion and the capital allocation line, and how this extends to the market portfolio and the capital market line"]}, {"title": "Simulation of Financial Asset Prices and Returns", "los": ["describe historical simulation and explain how it can be used in investment applications Quantitative Methods 3", "describe bootstrap resampling, and explain how it can be used in investment applications", "describe Monte Carlo simulation and explain how it can be used in investment applications"]}, {"title": "Applications of Simple Linear Regression in Finance", "los": ["describe, interpret, and explain simple linear regression, including coefficient estimation using the least squares criterion", "describe and compare the assumptions of simple linear regression, identify violations through analyzing residuals, evaluate the estimated model’s goodness-of-fit and regression coefficients, and results of ANOVA estimates", "calculate and interpret predicted values, the standard error of the estimate, and prediction intervals for the dependent variable in a simple linear regression model and describe different functional forms", "calculate and interpret the variable estimates of the capital asset pricing model (CAPM)"]}, {"title": "Introduction to Financial Data Science", "los": ["describe how big data, machine learning, and artificial intelligence are used in financial data science, fintech, and investment management Level I Topic Outlines"]}]}, {"id": "economics", "name": "Economics", "weight": "6–9%", "modules": [{"title": "The Firm and Market Structures", "los": ["determine and interpret breakeven and shutdown points of production, as well as how economies and diseconomies of scale affect costs under perfect and imperfect competition", "describe characteristics of perfect competition, monopolistic competition, oligopoly, and pure monopoly", "explain supply and demand relationships under monopolistic competition, including the optimal price and output for firms as well as pricing strategy", "explain supply and demand relationships under oligopoly, including the optimal price and output for firms as well as pricing strategy", "identify the type of market structure within which a firm operates and describe the use and limitations of concentration measures"]}, {"title": "Understanding Business Cycles", "los": ["describe the business cycle and its phases", "describe credit cycles", "describe how resource use, consumer and business activity, housing sector activity, and external trade sector activity vary over the business cycle and describe their measurement using economic indicators Economics"]}, {"title": "Fiscal Policy", "los": ["compare monetary and fiscal policy", "describe roles and objectives of fiscal policy as well as arguments as to whether the size of a national debt relative to GDP matters", "describe tools of fiscal policy, including their advantages and disadvantages", "explain the implementation of fiscal policy and difficulties of implementation as well as whether a fiscal policy is expansionary or contractionary"]}, {"title": "Monetary Policy", "los": ["describe the roles and objectives of central banks", "describe tools used to implement monetary policy tools and the monetary transmission mechanism, and explain the relationships between monetary policy and economic growth, inflation, interest, and exchange rates", "describe qualities of effective central banks; contrast their use of inflation, interest rate, and exchange rate targeting in expansionary or contractionary monetary policy; and describe the limitations of monetary policy", "explain the interaction of monetary and fiscal policy"]}, {"title": "Introduction to Geopolitics", "los": ["describe geopolitics from a cooperation versus competition perspective", "describe geopolitics and its relationship with globalization", "describe functions and objectives of the international organizations that facilitate trade, including the World Bank, the International Monetary Fund, and the World Trade Organization", "describe geopolitical risk", "describe tools of geopolitics and their impact on regions and economies", "describe the impact of geopolitical risk on investments"]}, {"title": "International Trade", "los": ["describe the benefits and costs of international trade", "compare types of trade restrictions, such as tariffs, quotas, and export subsidies, and their economic implications", "explain motivations for and advantages of trading blocs, common markets, and economic unions"]}, {"title": "Capital Flows and the FX Market", "los": ["describe the foreign exchange market, including its functions and participants, distinguish between nominal and real exchange rates, and calculate and interpret the percentage change in a currency relative to another currency", "describe exchange rate regimes and explain the effects of exchange rates on countries’ international trade and capital flows", "describe common objectives of capital restrictions imposed by governments Economics 7"]}, {"title": "Exchange Rate Calculations", "los": ["calculate and interpret currency cross-rates", "explain the arbitrage relationship between spot and forward exchange rates and interest rates, calculate a forward rate using points or in percentage terms, and interpret a forward discount or premium"]}]}, {"id": "corporate", "name": "Corporate Finance", "weight": "6–9%", "modules": [{"title": "Organizational Forms, Corporate Issuer Features, and Ownership", "los": ["compare the organizational forms of businesses", "describe key features of corporate issuers", "compare publicly and privately owned corporate issuers"]}, {"title": "Investors and Other Stakeholders", "los": ["compare the financial claims and motivations of lenders and shareholders", "describe a company’s stakeholder groups and compare their interests", "describe environmental, social, and governance factors of corporate issuers considered by investors"]}, {"title": "Corporate Governance: Conflicts, Mechanisms, Risks, and Benefits", "los": ["describe the principal-agent relationship and conflicts that may arise between stakeholder groups", "describe corporate governance and mechanisms to manage stakeholder relationships and mitigate associated risks", "describe potential risks of poor corporate governance and stakeholder management and benefits of effective corporate governance and stakeholder management Corporate Finance"]}, {"title": "Working Capital and Liquidity", "los": ["explain the cash conversion cycle and compare issuers’ cash conversion cycles", "explain liquidity and compare issuers’ liquidity levels", "describe issuers’ objectives and compare methods for managing working capital and liquidity"]}, {"title": "Capital Investments and Capital Allocation", "los": ["describe types of capital investments", "describe the capital allocation process, calculate net present value (NPV), internal rate of return (IRR), and return on invested capital (ROIC), and contrast their use in capital allocation", "describe principles of capital allocation and common capital allocation pitfalls", "describe types of real options relevant to capital investments"]}, {"title": "Capital Structure", "los": ["calculate and interpret the weighted-average cost of capital for a company", "explain factors affecting capital structure and the weighted-average cost of capital", "explain the Modigliani–Miller propositions regarding capital structure", "describe optimal and target capital structures"]}, {"title": "Business Models", "los": ["describe key features of business models", "describe various types of business models"]}]}, {"id": "fsa", "name": "Financial Statement Analysis", "weight": "11–14%", "modules": [{"title": "Introduction to Financial Statement Analysis", "los": ["describe the steps in the financial statement analysis framework", "describe the roles of financial statement analysis", "describe the importance of regulatory filings, financial statement notes and supplementary information, management’s commentary, and audit reports", "describe implications for financial analysis of alternative financial reporting systems and the importance of monitoring developments in financial reporting standards", "describe information sources that analysts use in financial statement analysis besides annual and interim financial reports"]}, {"title": "Analyzing Income Statements", "los": ["describe general principles of revenue recognition, specific revenue recognition applications, and implications of revenue recognition choices for financial analysis", "describe general principles of expense recognition, specific expense recognition applications, implications of expense recognition choices for financial analysis and contrast costs that are capitalized versus those that are expensed in the period in which they are incurred", "describe the financial reporting treatment and analysis of non-recurring items (including discontinued operations, unusual or infrequent items) and changes in accounting policies Financial Statement Analysis", "describe how earnings per share is calculated and calculate and interpret a company’s basic and diluted earnings per share for companies with simple and complex capital structures including those with antidilutive securities", "evaluate a company’s financial performance using common-size income statements and financial ratios based on the income statement"]}, {"title": "Analyzing Balance Sheets", "los": ["explain the financial reporting and disclosures related to intangible assets", "explain the financial reporting and disclosures related to goodwill", "explain the financial reporting and disclosures related to financial instruments", "explain the financial reporting and disclosures related to non-current liabilities", "calculate and interpret common-size balance sheets and related financial ratios"]}, {"title": "Analyzing Statements of Cash Flows I", "los": ["describe how the cash flow statement is linked to the income statement and the balance sheet", "describe the steps in the preparation of direct and indirect cash flow statements, including how cash flows can be computed using income statement and balance sheet data", "demonstrate the conversion of cash flows from the indirect to direct method", "contrast cash flow statements prepared under International Financial Reporting Standards (IFRS) and US generally accepted accounting principles (US GAAP)"]}, {"title": "Analyzing Statements of Cash Flows II", "los": ["analyze and interpret both reported and common-size cash flow statements", "calculate and interpret free cash flow to the firm, free cash flow to equity, and performance and coverage cash flow ratios"]}, {"title": "Analysis of Inventories", "los": ["describe the measurement of inventory at the lower of cost and net realisable value and its implications for financial statements and ratios", "calculate and explain how inflation and deflation of inventory costs affect the financial statements and ratios of companies that use different inventory valuation methods", "describe the presentation and disclosures relating to inventories and explain issues that analysts should consider when examining a company’s inventory disclosures and other sources of information"]}, {"title": "Analysis of Long-Term Assets", "los": ["compare the financial reporting of the following types of intangible assets: purchased, internally developed, and acquired in a business combination", "explain and evaluate how impairment and derecognition of property, plant, and equipment and intangible assets affect the financial statements and ratios", "analyze and interpret financial statement disclosures regarding property, plant, and equipment and intangible assets Financial Statement Analysis 13"]}, {"title": "Topics in Long-Term Liabilities and Equity", "los": ["explain the financial reporting of leases from the perspectives of lessors and lessees", "explain the financial reporting of defined contribution, defined benefit, and stock-based compensation plans", "describe the financial statement presentation of and disclosures relating to long-term liabilities and share-based compensation"]}, {"title": "Analysis of Income Taxes", "los": ["contrast accounting profit, taxable income, taxes payable, and income tax expense and temporary versus permanent differences between accounting profit and taxable income", "explain how deferred tax liabilities and assets are created and the factors that determine how a company’s deferred tax liabilities and assets should be treated for the purposes of financial analysis", "calculate, interpret, and contrast an issuer’s effective tax rate, statutory tax rate, and cash tax rate", "analyze disclosures relating to deferred tax items and the effective tax rate reconciliation and explain how information included in these disclosures affects a company’s financial statements and financial ratios"]}, {"title": "Financial Reporting Quality", "los": ["compare financial reporting quality with the quality of reported results (including quality of earnings, cash flow, and balance sheet items)", "describe a spectrum for assessing financial reporting quality", "explain the difference between conservative and aggressive accounting", "describe motivations that might cause management to issue financial reports that are not high quality and conditions that are conducive to issuing low-quality, or even fraudulent, financial reports", "describe mechanisms that discipline financial reporting quality and the potential limitations of those mechanisms", "describe presentation choices, including non-GAAP measures, that could be used to influence an analyst’s opinion", "describe accounting methods (choices and estimates) that could be used to manage earnings, cash flow, and balance sheet items", "describe accounting warning signs and methods for detecting manipulation of information in financial reports"]}, {"title": "Financial Analysis Techniques", "los": ["describe tools and techniques used in financial analysis, including their uses and limitations", "calculate and interpret activity, liquidity, solvency, and profitability ratios", "describe relationships among ratios and evaluate a company using ratio analysis", "demonstrate the application of DuPont analysis of return on equity and calculate and interpret effects of changes in its components", "describe the uses of industry-specific ratios used in financial analysis", "describe how ratio analysis and other techniques can be used to model and forecast earnings Financial Statement Analysis"]}, {"title": "Introduction to Financial Statement Modeling", "los": ["demonstrate the development of a sales-based pro forma company model", "explain how behavioral factors affect analyst forecasts and recommend remedial actions for analyst biases", "explain how the competitive position of a company based on a Porter’s five forces analysis affects prices and costs", "explain how to forecast industry and company sales and costs when they are subject to price inflation or deflation"]}]}, {"id": "equity", "name": "Equities", "weight": "11–14%", "modules": [{"title": "Equity Instrument Features", "los": ["describe basic features and types of equity instruments", "contrast features of publicly listed versus private equity securities"]}, {"title": "Equity Jurisdictions, Classes, and the Voting Process", "los": ["describe differences in economic and voting rights and other characteristics among different jurisdictions and equity classes", "describe the voting process and roles of the issuer’s management, board, proxy advisors, asset managers, and asset owners in the process"]}, {"title": "Equity Issuance and Trading", "los": ["describe primary and secondary public equity markets and their functions", "compare exchange, off-exchange, and over-the-counter equities trading", "describe liquidity measures for a publicly listed security and calculate float and average daily volume", "describe types of equity indexes Equities"]}, {"title": "Sources of Equity Returns", "los": ["describe features and uses of dividends, share repurchases, stock splits, and reverse stock splits", "describe dividend payment chronology", "calculate price and total return for equity securities"]}, {"title": "Introduction to Equity Valuation", "los": ["contrast price and value for an equity security", "contrast the use of book value of equity, market capitalization, and enterprise value as indicators of intrinsic value", "describe major categories of equity valuation models and explain their advantages and disadvantages"]}, {"title": "Discounted Cash Flow (DCF) and Growth Models", "los": ["contrast the inputs used in dividend discount, free cash flow to equity (FCFE), free cash flow to the firm (FCFF), and residual income models, and explain the process for using present value models to value equity", "calculate and interpret the intrinsic value of an equity security based on present value models that assume constant cash flow growth or multistage cash flow growth", "explain the shortcomings of constant and multistage cash flow growth assumptions in present value models", "calculate the intrinsic value of a non-callable, non-convertible preferred stock and describe how contingency features affect intrinsic value"]}, {"title": "Relative Value Equity Valuation Approaches", "los": ["explain the process for using multiples to value equity based on the method of comparables and the method of forecasted fundamentals", "calculate and interpret price and enterprise value multiples, and describe their appropriate uses", "determine a potential peer group for multiples-based equity valuation based on a company’s industry classification or specific drivers of expected return", "describe the use of multiples based on past, current, and projected future values in estimating equity value"]}, {"title": "Financial Statement Forecasting in Equity Valuation", "los": ["explain the rationale, construction, and uses of financial statement forecast models in equity valuation", "evaluate the construction of an equity valuation model based on characteristics of the subject company", "estimate and interpret the value of an equity security based on the outputs of a financial statement forecast model Equities 17"]}, {"title": "Industry and Competitive Analysis", "los": ["describe the process of industry and competitive analysis", "describe industry classification methods and compare methods by which companies can be grouped", "determine an industry’s size, growth characteristics, profitability, and market share trends", "analyze an industry’s structure and external influences using Porter’s Five Forces and the PESTLE framework"]}, {"title": "Company Analysis: Past, Present, and Future", "los": ["explain a company’s competitive strategy and position within an industry", "evaluate a company’s revenue drivers, operating profitability, and pricing power", "evaluate a company’s working capital, capital investments, and capital structure"]}, {"title": "Equity Analyst Research Reports", "los": ["describe the elements that should be covered in a detailed company research report", "compare sell-side and buy-side equity analyst reports and their conclusions", "explain why value estimates from the same modeling approach may differ based on analyst assumptions regarding revenue, profitability, investment, and financing The Capital Asset Pricing Model, Market Model, and Other Factor-Based Equity Models"]}]}, {"id": "fixed", "name": "Fixed Income", "weight": "11–14%", "modules": [{"title": "Fixed-Income Instrument Features", "los": ["describe the features of a fixed-income security", "describe the contents of a bond indenture and contrast affirmative and negative covenants"]}, {"title": "Fixed-Income Cash Flows and Types", "los": ["describe common cash flow structures of fixed-income instruments and contrast cash flow contingency provisions that benefit issuers and investors", "describe how legal, regulatory, and tax considerations affect the issuance and trading of fixed-income securities"]}, {"title": "Fixed-Income Issuance and Trading", "los": ["describe fixed-income market segments and their issuer and investor participants", "describe types of fixed-income indexes", "compare primary and secondary fixed-income markets to equity markets Fixed Income"]}, {"title": "Fixed-Income Markets for Corporate Issuers", "los": ["compare short-term funding alternatives available to corporations and financial institutions", "describe repurchase agreements (repos), their uses, and their benefits and risks", "contrast the long-term funding of investment-grade versus high-yield corporate issuers"]}, {"title": "Fixed-Income Markets for Government Issuers", "los": ["describe funding choices by sovereign and non-sovereign governments, quasi-government entities, and supranational agencies", "contrast the issuance and trading of government and corporate fixed-income instruments"]}, {"title": "Fixed-Income Bond Valuation: Prices and Yields", "los": ["calculate a bond’s price given a yield-to-maturity on or between coupon dates", "identify the relationships among a bond’s price, coupon rate, maturity, and yield-to-maturity", "describe matrix pricing"]}, {"title": "Yield and Yield Spread Measures for Fixed-Rate Bonds", "los": ["calculate annual yield on a bond for varying compounding periods in a year", "compare, calculate, and interpret yield and yield spread measures for fixed-rate bonds"]}, {"title": "Yield and Yield Spread Measures for Floating-Rate Instruments", "los": ["calculate and interpret yield spread measures for floating-rate instruments", "calculate and interpret yield measures for money market instruments"]}, {"title": "The Term Structure of Interest Rates: Spot, Par, and Forward Curves", "los": ["define spot rates and the spot curve, and calculate the price of a bond using spot rates", "define par and forward rates, and calculate par rates, forward rates from spot rates, spot rates from forward rates, and the price of a bond using forward rates", "compare the spot curve, par curve, and forward curve"]}, {"title": "Interest Rate Risk and Return", "los": ["calculate and interpret the sources of return from investing in a fixed-rate bond", "describe the relationships among a bond’s holding period return, its Macaulay duration, and the investment horizon", "define, calculate, and interpret Macaulay duration. Fixed Income 21"]}, {"title": "Yield-Based Bond Duration Measures and Properties", "los": ["define, calculate, and interpret modified duration, money duration, and the price value of a basis point (PVBP)", "explain how a bond’s maturity, coupon, and yield level affect its interest rate risk"]}, {"title": "Yield-Based Bond Convexity and Portfolio Properties", "los": ["calculate and interpret convexity and describe the convexity adjustment", "calculate the percentage price change of a bond for a specified change in yield, given the bond’s duration and convexity", "calculate portfolio duration and convexity and explain the limitations of these measures"]}, {"title": "Curve-Based and Empirical Fixed-Income Risk Measures", "los": ["explain why effective duration and effective convexity are the most appropriate measures of interest rate risk for bonds with embedded options", "calculate the percentage price change of a bond for a specified change in benchmark yield, given the bond’s effective duration and convexity", "define key rate duration and describe its use to measure price sensitivity of fixed-income instruments to benchmark yield curve changes", "describe the difference between empirical duration and analytical duration"]}, {"title": "Credit Risk", "los": ["describe credit risk and its components, probability of default and loss given default", "describe the uses of ratings from credit rating agencies and their limitations", "describe macroeconomic, market, and issuer-specific factors that influence the level and volatility of yield spreads"]}, {"title": "Credit Analysis for Government Issuers", "los": ["explain special considerations when evaluating the credit of sovereign and non-sovereign government debt issuers and issues"]}, {"title": "Credit Analysis for Corporate Issuers", "los": ["describe the qualitative and quantitative factors used to evaluate a corporate borrower’s creditworthiness", "calculate and interpret financial ratios used in credit analysis", "describe the seniority rankings of debt, secured versus unsecured debt and the priority of claims in bankruptcy, and their impact on credit ratings"]}, {"title": "Fixed-Income Securitization", "los": ["explain benefits of securitization for issuers, investors, economies, and financial markets", "describe securitization, including the parties and the roles they play Fixed Income"]}, {"title": "Asset-Backed Security (ABS) Instrument and Market Features", "los": ["describe characteristics and risks of covered bonds and how they differ from other asset-backed securities", "describe typical credit enhancement structures used in securitizations", "describe types and characteristics of non-mortgage asset-backed securities, including the cash flows and risks of each type"]}]}, {"id": "derivatives", "name": "Derivatives", "weight": "5–8%", "modules": [{"title": "Mortgage-Backed Security (MBS) Instrument and Market Features", "los": ["define prepayment risk and describe time tranching structures in securitizations and their purpose", "describe fundamental features of residential mortgage loans that are securitized", "describe types and characteristics of residential mortgage-backed securities, including mortgage pass-through securities and collateralized mortgage obligations, and explain the cash flows and risks for each type", "describe characteristics and risks of commercial mortgage-backed securities Level I Topic Outlines Derivatives LEARNING OUTCOMES"]}, {"title": "Derivative Instrument and Derivative Market Features", "los": ["define a derivative and describe basic features of a derivative instrument", "describe the basic features of derivative markets, and contrast over-the-counter and exchange-traded derivative markets"]}, {"title": "Forward Commitment and Contingent Claim Features and Instruments", "los": ["define forward contracts, futures contracts, swaps, options (calls and puts), and credit derivatives and compare their basic characteristics", "determine the value at expiration and profit from a long or a short position in a call or put option", "contrast forward commitments with contingent claims"]}, {"title": "Derivative Benefits, Risks, and Issuer and Investor Uses", "los": ["describe benefits and risks of derivative instruments", "compare the use of derivatives among issuers and investors"]}, {"title": "Arbitrage, Replication, and the Cost of Carry in Pricing Derivatives", "los": ["explain how the concepts of arbitrage and replication are used in pricing derivatives Derivatives", "explain the difference between the spot and expected future price of an underlying and the cost of carry associated with holding the underlying asset Pricing and Valuation of Forward Contracts and for an Underlying with Varying"]}, {"title": "Pricing and Valuation of Forward Contracts and for an Underlying with Varying Maturities", "los": ["explain how the value and price of a forward contract are determined at initiation, during the life of the contract, and at expiration", "explain how forward rates are determined for interest rate forward contracts and describe the uses of these forward rates."]}, {"title": "Pricing and Valuation of Futures Contracts", "los": ["compare the value and price of forward and futures contracts", "explain why forward and futures prices differ"]}, {"title": "Pricing and Valuation of Interest Rate and Other Swaps", "los": ["describe how swap contracts are similar to but different from a series of forward contracts", "contrast the value and price of swaps"]}, {"title": "Pricing and Valuation of Options", "los": ["explain the exercise value, moneyness, and time value of an option", "contrast the use of arbitrage and replication concepts in pricing forward"]}]}, {"id": "alternatives", "name": "Alternative Investments", "weight": "7–10%", "modules": [{"title": "Option Replication Using Put–Call Parity", "los": ["explain put–call parity for European options", "explain put–call forward parity for European options"]}, {"title": "Valuing a Derivative Using a One-Period Binomial Model", "los": ["explain how to value a derivative using a one-period binomial model", "describe the concept of risk neutrality in derivatives pricing Level I Topic Outlines Alternative Investments LEARNING OUTCOMES"]}, {"title": "Alternative Investment Features, Methods, and Structures", "los": ["describe features and categories of alternative investments", "compare direct investment, co-investment, and fund investment methods for alternative investments", "describe investment ownership and compensation structures commonly used in alternative investments"]}, {"title": "Alternative Investment Performance and Returns", "los": ["describe the performance appraisal of alternative investments", "calculate and interpret alternative investment returns both before and after fees"]}, {"title": "Investments in Private Capital: Equity and Debt", "los": ["explain features of private equity and its investment characteristics", "explain features of private debt and its investment characteristics", "describe the diversification benefits that private capital can provide"]}, {"title": "Real Estate and Infrastructure", "los": ["explain features and characteristics of real estate", "explain the investment characteristics of real estate investments Alternative Investments", "explain features and characteristics of infrastructure", "explain the investment characteristics of infrastructure investments"]}, {"title": "Natural Resources", "los": ["explain features of raw land, timberland, and farmland and their investment characteristics", "describe features of commodities and their investment characteristics", "analyze sources of risk, return, and diversification among natural resource investments Hedge Funds"]}]}, {"id": "portfolio", "name": "Portfolio Construction", "weight": "8–12%", "modules": [{"title": "Introduction to Digital Assets", "los": ["describe financial applications of distributed ledger technology", "explain investment features of digital assets and contrast them with other asset classes", "describe investment forms and vehicles used in digital asset investments", "analyze sources of risk, return, and diversification among digital asset investments Level I Topic Outlines Portfolio Construction LEARNING OUTCOMES"]}, {"title": "Portfolio Risk and Return: Part I", "los": ["describe characteristics of the major asset classes that investors consider in forming portfolios", "explain risk aversion and its implications for portfolio selection", "explain the selection of an optimal portfolio, given an investor’s utility (or risk aversion) and the capital allocation line", "calculate and interpret the mean, variance, and covariance (or correlation) of asset returns based on historical data", "calculate and interpret portfolio standard deviation", "describe the effect on a portfolio’s risk of investing in assets that are less than perfectly correlated", "describe and interpret the minimum-variance and efficient frontiers of risky assets and the global minimum-variance portfolio"]}, {"title": "Portfolio Risk and Return: Part II", "los": ["describe the implications of combining a risk-free asset with a portfolio of risky assets", "explain the capital allocation line (CAL) and the capital market line (CML)", "explain systematic and nonsystematic risk, including why an investor should not expect to receive additional return for bearing nonsystematic risk", "explain return generating models (including the market model) and their uses", "calculate and interpret beta Portfolio Construction", "explain the capital asset pricing model (CAPM), including its assumptions, and the security market line (SML)", "calculate and interpret the expected return of an asset using the CAPM", "describe and demonstrate applications of the CAPM and the SML", "calculate and interpret the Sharpe ratio, Treynor ratio, M2, and Jensen’s alpha"]}, {"title": "Portfolio Management: An Overview", "los": ["describe the portfolio approach to investing", "describe the steps in the portfolio management process", "describe types of investors and distinctive characteristics and needs of each", "describe defined contribution and defined benefit pension plans", "describe aspects of the asset management industry", "describe mutual funds and compare them with other pooled investment products"]}, {"title": "Basics of Portfolio Planning and Construction", "los": ["describe the reasons for a written investment policy statement (IPS)", "describe the major components of an IPS", "describe risk and return objectives and how they may be developed for a client", "explain the difference between the willingness and the ability (capacity) to take risk in analyzing an investor’s financial risk tolerance", "describe the investment constraints of liquidity, time horizon, tax concerns, legal and regulatory factors, and unique circumstances and their implications for the choice of portfolio assets", "explain the specification of asset classes in relation to asset allocation", "describe the principles of portfolio construction and the role of asset allocation in relation to the IPS", "describe how environmental, social, and governance (ESG) considerations may be integrated into portfolio planning and construction"]}]}, {"id": "ethics", "name": "Ethical and Professional Standards", "weight": "15–20%", "modules": [{"title": "Introduction to Risk Management", "los": ["define risk management", "describe features of a risk management framework", "define risk governance and describe elements of effective risk governance", "explain how risk tolerance affects risk management", "describe risk budgeting and its role in risk governance", "identify financial and non-financial sources of risk and describe how they may interact", "describe methods for measuring and modifying risk exposures and factors to consider in choosing among the methods Level I Topic Outlines Ethical and Professional Standards LEARNING OUTCOMES"]}, {"title": "Ethics and Trust in the Investment Profession", "los": ["explain ethics", "describe the role of a code of ethics in defining a profession", "describe professions and how they establish trust", "describe the need for high ethical standards in investment management", "explain professionalism in investment management", "identify challenges to ethical behavior", "compare and contrast ethical standards with legal standards", "describe a framework for ethical decision-making"]}, {"title": "Code of Ethics and Standards of Professional Conduct", "los": ["describe the structure of the CFA Institute Professional Conduct Program and the process for the enforcement of the Code and Standards", "identify the six components of the Code of Ethics and the seven Standards of Professional Conduct", "explain the ethical responsibilities required by the Code and Standards, including the sub-sections of each Standard Ethical and Professional Standards"]}, {"title": "Guidance for Standard I: Professionalism", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard II: Integrity of Capital Markets", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard III: Duties to Clients", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard IV: Duties to Employers", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard V: Investment Analysis, Recommendations, and Actions", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards"]}, {"title": "Guidance for Standard VI: Conflicts of Interest", "los": ["demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity Ethical and Professional Standards 31", "recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct", "identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards Guidance for Standard VII: Responsibilities as a"]}, {"title": "Guidance for Standard VII: Responsibilities as a CFA Institute Member or CFA Candidate", "los": ["demonstrate a thorough knowledge of the CFA Institute Code of Ethics and Standards of Professional Conduct by interpreting the Code and Standards in various situations involving issues of professional integrity", "recommend practices and procedures designed to prevent violations of the Code and Standards"]}, {"title": "Application of the Code and Standards: Level I", "los": ["evaluate practices, policies, and conduct relative to the CFA Institute Code of Ethics and Standards of Professional Conduct", "explain how the practices, policies, and conduct do or do not violate the CFA Institute Code of Ethics and Standards of Professional Conduct"]}]}], "questions": [{"topic": "quant", "q": "A portfolio earns 20% in year 1 and loses 20% in year 2. Its two-year geometric mean annual return is closest to:", "choices": ["−2.0%", "0.0%", "2.0%"], "a": 0, "why": "Ending wealth is 1.20×0.80=0.96. √0.96−1≈−2.02%."}, {"topic": "quant", "q": "The present value of 121 received in two years at 10% annually is:", "choices": ["100", "110", "121"], "a": 0, "why": "121/(1.10)^2 = 100."}, {"topic": "quant", "q": "Compared with the arithmetic mean, the geometric mean of a variable return series is generally:", "choices": ["greater", "equal or lower", "always negative"], "a": 1, "why": "Volatility drag makes the geometric mean no greater than the arithmetic mean."}, {"topic": "quant", "q": "A larger sample size, all else equal, most likely causes the standard error of the sample mean to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "Standard error is s/√n."}, {"topic": "quant", "q": "A p-value is best described as the probability, assuming the null is true, of observing:", "choices": ["the null hypothesis", "a result at least as extreme as the sample result", "a Type II error"], "a": 1, "why": "The p-value measures how unusual the result is under the null."}, {"topic": "quant", "q": "Failure to reject a null hypothesis means the analyst should conclude that the null is:", "choices": ["proven true", "not rejected with the available evidence", "false"], "a": 1, "why": "Failure to reject is not proof of truth."}, {"topic": "quant", "q": "A correlation coefficient of −1 indicates:", "choices": ["no relationship", "a perfect negative linear relationship", "a nonlinear positive relationship"], "a": 1, "why": "−1 is perfect negative linear association."}, {"topic": "quant", "q": "Which return measure is most affected by the timing and size of external cash flows?", "choices": ["Time-weighted return", "Money-weighted return", "Geometric mean return"], "a": 1, "why": "Money-weighted return is an IRR and reflects cash-flow timing."}, {"topic": "quant", "q": "In simple linear regression, the slope coefficient measures the expected change in:", "choices": ["X for a one-unit change in Y", "Y for a one-unit change in X", "the error term for a one-unit change in X"], "a": 1, "why": "The slope is the change in dependent variable Y per unit of X."}, {"topic": "quant", "q": "Monte Carlo simulation differs from historical simulation because Monte Carlo most directly uses:", "choices": ["only actual historical observations", "random draws from an assumed model", "no probability distribution"], "a": 1, "why": "Monte Carlo generates random scenarios from a specified model or distribution."}, {"topic": "economics", "q": "An increase in consumer income for a normal good most likely shifts:", "choices": ["demand left", "demand right", "supply right"], "a": 1, "why": "Demand for a normal good rises with income."}, {"topic": "economics", "q": "If demand is price inelastic, a price increase will most likely cause total revenue to:", "choices": ["increase", "decrease", "remain exactly unchanged"], "a": 0, "why": "Quantity falls proportionally less than price rises."}, {"topic": "economics", "q": "A binding minimum wage is an example of a:", "choices": ["price ceiling", "price floor", "quantity subsidy"], "a": 1, "why": "It sets a minimum price for labor."}, {"topic": "economics", "q": "In perfect competition, an individual firm is best described as a:", "choices": ["price maker", "price taker", "monopolist"], "a": 1, "why": "Many sellers and homogeneous products leave firms without pricing power."}, {"topic": "economics", "q": "Real GDP differs from nominal GDP because real GDP adjusts for changes in:", "choices": ["population only", "the price level", "net exports only"], "a": 1, "why": "Real GDP measures output using constant prices."}, {"topic": "economics", "q": "Expansionary monetary policy most directly aims initially to:", "choices": ["reduce liquidity", "lower short-term interest rates or ease financial conditions", "raise taxes"], "a": 1, "why": "Central banks typically add liquidity or reduce policy rates."}, {"topic": "economics", "q": "A currency quoted as SEK/USD = 10.50 means:", "choices": ["one SEK costs USD 10.50", "one USD costs SEK 10.50", "ten USD cost SEK 0.50"], "a": 1, "why": "The quote is units of SEK per USD."}, {"topic": "economics", "q": "A country running a current-account deficit must, in accounting terms, have an offsetting:", "choices": ["capital and financial account surplus", "government budget surplus", "trade surplus"], "a": 0, "why": "Balance-of-payments accounts must offset, subject to statistical discrepancy."}, {"topic": "economics", "q": "A leading economic indicator is intended to:", "choices": ["change after the economy", "turn before broad economic activity", "measure only inflation"], "a": 1, "why": "Leading indicators tend to turn ahead of the overall cycle."}, {"topic": "economics", "q": "An increase in expected inflation, all else equal, most likely causes nominal interest rates to:", "choices": ["fall", "rise", "remain fixed by definition"], "a": 1, "why": "The Fisher relation links nominal rates to real rates and expected inflation."}, {"topic": "corporate", "q": "A sunk cost in capital budgeting should generally be:", "choices": ["included as an outflow", "excluded", "discounted at the risk-free rate"], "a": 1, "why": "It has already occurred and is not incremental."}, {"topic": "corporate", "q": "An opportunity cost is best described as:", "choices": ["a past expenditure", "the value of the best alternative forgone", "a noncash accounting charge"], "a": 1, "why": "Using a resource sacrifices its best alternative use."}, {"topic": "corporate", "q": "For mutually exclusive projects with conflicting rankings, the preferred value-maximizing criterion is usually:", "choices": ["payback", "NPV", "accounting return"], "a": 1, "why": "NPV measures expected value added."}, {"topic": "corporate", "q": "Interest expense is normally excluded from project free cash flows when discounting at WACC because financing cost is:", "choices": ["irrelevant", "already reflected in WACC", "always tax-free"], "a": 1, "why": "Including it would double count financing effects."}, {"topic": "corporate", "q": "An increase in days receivables, all else equal, will most likely:", "choices": ["shorten the cash conversion cycle", "lengthen the cash conversion cycle", "have no effect"], "a": 1, "why": "CCC includes receivable days positively."}, {"topic": "corporate", "q": "Greater fixed operating costs, all else equal, generally cause operating leverage to:", "choices": ["increase", "decrease", "become zero"], "a": 0, "why": "Fixed costs magnify changes in operating profit as sales change."}, {"topic": "corporate", "q": "The after-tax cost of debt equals:", "choices": ["rd(1−T)", "rd/(1−T)", "rd+T"], "a": 0, "why": "Interest tax deductibility creates the tax shield."}, {"topic": "corporate", "q": "A project with risk above the firm's average should generally be evaluated using a discount rate that is:", "choices": ["below WACC", "above WACC", "always equal to WACC"], "a": 1, "why": "Higher risk requires a higher appropriate required return."}, {"topic": "corporate", "q": "A board composed entirely of executives may raise concern primarily about:", "choices": ["independence of oversight", "lack of operating knowledge", "excess liquidity"], "a": 0, "why": "Independent oversight can be weakened."}, {"topic": "corporate", "q": "Aggressive working-capital policy typically uses relatively:", "choices": ["more long-term financing and higher liquidity", "less long-term financing and lower liquidity", "no short-term financing"], "a": 1, "why": "Aggressive policy trades lower financing cost for greater liquidity/refinancing risk."}, {"topic": "fsa", "q": "A company sells goods on credit. At the sale date, revenue increases but cash flow from operations:", "choices": ["necessarily increases immediately", "does not necessarily increase immediately", "is classified as financing"], "a": 1, "why": "Cash is not collected at the sale date."}, {"topic": "fsa", "q": "Depreciation is added back to net income under the indirect method because it is:", "choices": ["a financing inflow", "a noncash expense", "an investing outflow in the current period"], "a": 1, "why": "It reduced net income without using current-period cash."}, {"topic": "fsa", "q": "A current ratio above 1 means current assets are:", "choices": ["greater than current liabilities", "less than current liabilities", "equal to equity"], "a": 0, "why": "Current ratio = current assets/current liabilities."}, {"topic": "fsa", "q": "Using average inventory rather than ending inventory in turnover ratios primarily improves:", "choices": ["period matching", "tax deductibility", "audit independence"], "a": 0, "why": "The income-statement flow covers a period and should be matched to an average balance."}, {"topic": "fsa", "q": "Capitalizing a cost rather than expensing it immediately will initially report:", "choices": ["higher assets and higher profit", "lower assets and higher profit", "higher assets and lower profit"], "a": 0, "why": "Expense is deferred and an asset is recognized."}, {"topic": "fsa", "q": "An impairment loss generally causes assets and current-period profit to:", "choices": ["both increase", "both decrease", "remain unchanged"], "a": 1, "why": "The asset is written down and a loss is recognized."}, {"topic": "fsa", "q": "A deferred tax liability commonly arises when tax depreciation is initially:", "choices": ["slower than accounting depreciation", "faster than accounting depreciation", "equal to accounting depreciation forever"], "a": 1, "why": "Faster tax depreciation lowers current tax but creates future taxable amounts."}, {"topic": "fsa", "q": "Diluted EPS includes potential common shares only when they are:", "choices": ["antidilutive", "dilutive", "secured"], "a": 1, "why": "Antidilutive instruments are excluded."}, {"topic": "fsa", "q": "High net income accompanied by persistently weak operating cash flow may indicate:", "choices": ["stronger earnings quality", "a need for closer earnings-quality analysis", "zero credit risk"], "a": 1, "why": "Cash conversion and accrual quality require investigation."}, {"topic": "fsa", "q": "An unmodified audit opinion means the financial statements are presented fairly in material respects; it does not guarantee:", "choices": ["compliance with the reporting framework", "future profitability", "that an audit occurred"], "a": 1, "why": "The opinion is not a guarantee of performance or absence of all fraud."}, {"topic": "equity", "q": "A market order prioritizes:", "choices": ["price certainty", "execution certainty", "dividend income"], "a": 1, "why": "It seeks immediate execution at available prices."}, {"topic": "equity", "q": "A buy limit order sets the:", "choices": ["maximum purchase price", "minimum purchase price", "exact execution price guaranteed"], "a": 0, "why": "The buyer will not pay above the limit."}, {"topic": "equity", "q": "A market-capitalization-weighted index gives more weight to companies with:", "choices": ["higher share price only", "larger equity market value", "higher dividend yield"], "a": 1, "why": "Weight is based on market capitalization."}, {"topic": "equity", "q": "Semi-strong market efficiency states that prices reflect:", "choices": ["past prices only", "all public information", "all public and private information"], "a": 1, "why": "Semi-strong efficiency includes all publicly available information."}, {"topic": "equity", "q": "A competitive advantage creates value only if it supports returns on invested capital that are:", "choices": ["below the cost of capital", "above the cost of capital", "equal to inflation"], "a": 1, "why": "Value is created when returns exceed the opportunity cost of capital."}, {"topic": "equity", "q": "A higher required return in the Gordon model, all else equal, causes value to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "It increases the denominator r−g."}, {"topic": "equity", "q": "Enterprise value is conceptually the value available to:", "choices": ["common shareholders only", "all capital providers", "employees only"], "a": 1, "why": "It reflects the operating asset value before allocation between debt and equity."}, {"topic": "equity", "q": "A scenario-weighted value should use scenario probabilities that:", "choices": ["sum to 100%", "sum to the discount rate", "are all equal"], "a": 0, "why": "They represent a complete probability distribution."}, {"topic": "equity", "q": "A low P/E multiple may reflect:", "choices": ["undervaluation only", "low expected growth or high risk", "guaranteed superior returns"], "a": 1, "why": "Multiples embed growth, risk, profitability, and accounting effects."}, {"topic": "equity", "q": "When valuing a stable dividend-paying firm with constant sustainable growth, the most directly applicable model is:", "choices": ["Gordon growth model", "liquidation model only", "historical-cost model"], "a": 0, "why": "The Gordon model fits stable perpetual dividend growth below required return."}, {"topic": "fixed", "q": "A bond's coupon rate determines its:", "choices": ["contractual coupon payment", "market discount rate", "credit spread"], "a": 0, "why": "Coupon rate × par determines coupon cash flow."}, {"topic": "fixed", "q": "A premium bond has a coupon rate that is generally:", "choices": ["above its yield to maturity", "below its yield to maturity", "zero"], "a": 0, "why": "Higher coupon than required yield produces price above par."}, {"topic": "fixed", "q": "If required yield falls, an option-free bond's price most likely:", "choices": ["falls", "rises", "remains at par"], "a": 1, "why": "Price and yield move inversely."}, {"topic": "fixed", "q": "A longer-duration bond is generally:", "choices": ["less price-sensitive to yield changes", "more price-sensitive to yield changes", "free of reinvestment risk"], "a": 1, "why": "Duration measures first-order price sensitivity."}, {"topic": "fixed", "q": "Positive convexity means the price gain from a yield decline is generally:", "choices": ["smaller than the price loss from an equal rise", "larger than the price loss from an equal rise", "always zero"], "a": 1, "why": "The price–yield curve is convex."}, {"topic": "fixed", "q": "A callable bond most likely experiences price compression when rates:", "choices": ["fall substantially", "rise substantially", "remain unchanged"], "a": 0, "why": "The issuer's call option becomes more valuable."}, {"topic": "fixed", "q": "Credit spread widening, all else equal, most likely causes a corporate bond's price to:", "choices": ["rise", "fall", "remain unchanged"], "a": 1, "why": "A higher required spread raises the discount rate."}, {"topic": "fixed", "q": "Loss given default equals one minus the:", "choices": ["coupon rate", "recovery rate", "default probability"], "a": 1, "why": "LGD = 1 − recovery rate."}, {"topic": "fixed", "q": "Mortgage prepayments tend to accelerate when interest rates:", "choices": ["fall", "rise", "are unrelated to refinancing"], "a": 0, "why": "Borrowers refinance when cheaper funding becomes available."}, {"topic": "fixed", "q": "A forward rate can be interpreted as a rate implied by:", "choices": ["spot rates under no-arbitrage", "coupon rates only", "historical inflation only"], "a": 0, "why": "Forward rates are derived from the spot curve."}, {"topic": "derivatives", "q": "A long call option has maximum loss equal to:", "choices": ["the strike price", "the premium paid", "unlimited loss"], "a": 1, "why": "The holder can let the option expire."}, {"topic": "derivatives", "q": "A short call position has potential loss that is:", "choices": ["limited to premium", "potentially unlimited", "always zero"], "a": 1, "why": "The underlying can rise without a fixed upper bound."}, {"topic": "derivatives", "q": "A put option is in the money at expiration when:", "choices": ["ST > X", "ST < X", "ST = premium"], "a": 1, "why": "The right to sell at X is valuable when market price is below X."}, {"topic": "derivatives", "q": "A forward contract normally has an initial value close to:", "choices": ["zero", "the spot price", "the full notional"], "a": 0, "why": "The delivery price is set so neither side pays at initiation, absent special terms."}, {"topic": "derivatives", "q": "Futures differ from forwards most directly because futures are:", "choices": ["marked to market daily", "always privately negotiated", "free of margin"], "a": 0, "why": "Daily settlement is a key futures feature."}, {"topic": "derivatives", "q": "An interest-rate swap can be viewed conceptually as:", "choices": ["a series of forward contracts", "an equity share", "a physical commodity only"], "a": 0, "why": "Each settlement resembles a forward-rate agreement."}, {"topic": "derivatives", "q": "Higher expected volatility, all else equal, generally causes the value of both calls and puts to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 0, "why": "Option holders benefit from greater dispersion with limited downside."}, {"topic": "derivatives", "q": "Put–call parity is fundamentally based on:", "choices": ["identical expiration payoffs and no-arbitrage", "historical average returns", "accounting book value"], "a": 0, "why": "Portfolios with identical payoffs should have identical prices."}, {"topic": "derivatives", "q": "The intrinsic value of a call before expiration is:", "choices": ["max(0,S−X)", "max(0,X−S)", "premium plus strike"], "a": 0, "why": "Immediate exercise value is the positive difference between spot and strike."}, {"topic": "derivatives", "q": "A protective put combines:", "choices": ["long stock and long put", "short stock and short put", "long call and short stock"], "a": 0, "why": "The put limits downside on the stock."}, {"topic": "alternatives", "q": "Infrequent appraisal-based pricing most likely causes measured return volatility to be:", "choices": ["smoothed downward", "artificially increased", "exactly unbiased"], "a": 0, "why": "Stale and smoothed appraisals understate short-term variation."}, {"topic": "alternatives", "q": "The private-equity J-curve describes:", "choices": ["weak early net returns followed by possible later gains", "constant annual gains", "a bond price–yield curve"], "a": 0, "why": "Fees and immature investments depress early results."}, {"topic": "alternatives", "q": "A higher capitalization rate, all else equal, causes property value to:", "choices": ["rise", "fall", "remain unchanged"], "a": 1, "why": "Value = NOI/cap rate."}, {"topic": "alternatives", "q": "Survivorship bias in a hedge-fund index most likely biases returns:", "choices": ["upward", "downward", "to exactly zero"], "a": 0, "why": "Failed funds are removed, leaving stronger survivors."}, {"topic": "alternatives", "q": "Backfill bias arises when a fund adds:", "choices": ["selected favorable prior returns after joining a database", "future forecasts only", "audited fees only"], "a": 0, "why": "Historical data are often added after good performance."}, {"topic": "alternatives", "q": "Commodity futures return can differ from spot return because of:", "choices": ["roll yield and collateral yield", "dividends only", "book depreciation"], "a": 0, "why": "Futures exposure adds term-structure roll and collateral effects."}, {"topic": "alternatives", "q": "Infrastructure investments often involve:", "choices": ["short-lived assets with no regulation", "long-lived assets and regulatory or concession risk", "only listed common stock"], "a": 1, "why": "Projects are long duration and frequently regulated or concession-based."}, {"topic": "alternatives", "q": "Carried interest is best described as:", "choices": ["a performance-based share of profits", "a custody fee only", "the risk-free rate"], "a": 0, "why": "Managers may receive a share of profits above specified terms."}, {"topic": "alternatives", "q": "Private-market reported returns may be less comparable because of differences in:", "choices": ["valuation timing and methodology", "arithmetic rules", "currency symbols only"], "a": 0, "why": "Valuation discretion and timing affect reported performance."}, {"topic": "alternatives", "q": "Digital-asset custody risk concerns:", "choices": ["control and safekeeping of access credentials/assets", "coupon reinvestment", "inventory turnover"], "a": 0, "why": "Loss, theft, or failure of custody arrangements can impair ownership or access."}, {"topic": "portfolio", "q": "Portfolio expected return is the:", "choices": ["weighted average of asset expected returns", "sum of asset variances", "highest asset return"], "a": 0, "why": "Expected return is linear in portfolio weights."}, {"topic": "portfolio", "q": "Portfolio variance depends importantly on:", "choices": ["covariances among assets", "expected returns only", "number of accounts"], "a": 0, "why": "Co-movement determines diversification."}, {"topic": "portfolio", "q": "Adding an asset with low correlation to an existing portfolio most likely:", "choices": ["improves diversification", "guarantees higher return", "eliminates all risk"], "a": 0, "why": "Low correlation can reduce portfolio variance."}, {"topic": "portfolio", "q": "Beta measures sensitivity to:", "choices": ["systematic market movements", "firm-specific events only", "accounting earnings only"], "a": 0, "why": "Beta is covariance with the market scaled by market variance."}, {"topic": "portfolio", "q": "A security plotting above the security market line has a return that is:", "choices": ["higher than CAPM-required return for its beta", "lower than the risk-free rate by definition", "exactly equal to alpha zero"], "a": 0, "why": "It offers positive alpha relative to CAPM."}, {"topic": "portfolio", "q": "Risk capacity refers to the investor's:", "choices": ["financial ability to bear losses", "emotional preference only", "forecast accuracy"], "a": 0, "why": "Capacity is economic ability; willingness is psychological."}, {"topic": "portfolio", "q": "For an investor with high willingness but low ability to bear risk, the portfolio should generally reflect:", "choices": ["the lower ability", "the higher willingness", "unlimited leverage"], "a": 0, "why": "The more restrictive dimension governs."}, {"topic": "portfolio", "q": "The investment policy statement should normally document:", "choices": ["objectives and constraints", "only past returns", "guaranteed future performance"], "a": 0, "why": "The IPS guides portfolio decisions and accountability."}, {"topic": "portfolio", "q": "Rebalancing restores:", "choices": ["target asset weights", "the highest recent-return asset", "zero transaction costs"], "a": 0, "why": "It brings exposures back toward policy targets."}, {"topic": "portfolio", "q": "The Sharpe ratio measures excess return per unit of:", "choices": ["total volatility", "beta only", "tracking error only"], "a": 0, "why": "The denominator is standard deviation."}, {"topic": "ethics", "q": "When local law is less strict than the professional standard, a member should generally follow:", "choices": ["the stricter professional standard", "local law only in all cases", "the employer's preference"], "a": 0, "why": "Follow the stricter applicable requirement unless doing so violates law."}, {"topic": "ethics", "q": "Information is material when its disclosure would likely:", "choices": ["affect an investor's decision or the security's price", "interest only one employee", "already be fully public"], "a": 0, "why": "Materiality concerns decision or price significance."}, {"topic": "ethics", "q": "Mosaic theory permits use of:", "choices": ["public information plus immaterial nonpublic information", "material nonpublic information", "client-confidential orders"], "a": 0, "why": "Material nonpublic information remains prohibited."}, {"topic": "ethics", "q": "A member receiving additional compensation that may conflict with employer interests should obtain:", "choices": ["written consent from relevant parties", "oral consent from a friend", "no consent if performance is good"], "a": 0, "why": "Written consent allows informed evaluation of the conflict."}, {"topic": "ethics", "q": "Fair dealing requires members to provide clients:", "choices": ["a fair opportunity to act on recommendations", "identical outcomes", "guaranteed simultaneous receipt under all technical conditions"], "a": 0, "why": "The obligation is fair treatment and opportunity, not guaranteed identical results."}, {"topic": "ethics", "q": "A recommendation should have:", "choices": ["a reasonable and adequate basis", "only management's opinion", "a guaranteed target price"], "a": 0, "why": "Diligence and a reasonable basis are required."}, {"topic": "ethics", "q": "A member preparing to leave an employer may generally:", "choices": ["make arrangements that do not misuse records or solicit clients before departure", "take confidential client lists", "delete employer files"], "a": 0, "why": "Preparation is allowed, but loyalty and property duties remain."}, {"topic": "ethics", "q": "Performance presentation should be:", "choices": ["fair, accurate, and complete", "selected to show only winning accounts", "guaranteed"], "a": 0, "why": "Selective or misleading presentation violates professional duties."}, {"topic": "ethics", "q": "A conflict disclosure should be:", "choices": ["prominent and understandable", "hidden in technical footnotes", "made only after a transaction"], "a": 0, "why": "Clients need clear disclosure before relying on advice."}, {"topic": "ethics", "q": "If a supervisor discovers a likely violation, the supervisor should most appropriately:", "choices": ["take reasonable steps to prevent or address it", "ignore it without investigation", "destroy relevant records"], "a": 0, "why": "Supervisory responsibility includes reasonable prevention and remediation."}, {"topic": "quant", "q": "An investment of 1,000 grows to 1,331 in three years. The annual compound return is closest to:", "choices": ["9%", "10%", "11%"], "a": 1, "why": "1,331/1,000 = 1.331 = 1.10^3, so the annual return is 10%.", "losRef": ""}, {"topic": "quant", "q": "If a distribution is positively skewed, the mean is most likely:", "choices": ["less than the median", "greater than the median", "equal to the mode"], "a": 1, "why": "Large positive observations pull the mean to the right, commonly giving mean > median > mode.", "losRef": ""}, {"topic": "quant", "q": "Variance is expressed in:", "choices": ["the original units", "squared units", "unit-free percentages only"], "a": 1, "why": "Variance averages squared deviations; standard deviation returns to the original units.", "losRef": ""}, {"topic": "quant", "q": "Conditional probability P(A|B) is calculated as:", "choices": ["P(A and B)/P(B)", "P(A)/P(B)", "P(B and A)/P(A)"], "a": 0, "why": "By definition, P(A|B)=P(A∩B)/P(B), provided P(B)>0.", "losRef": ""}, {"topic": "quant", "q": "A 95% confidence interval becomes narrower, all else equal, when:", "choices": ["sample size increases", "confidence level increases", "sample variability increases"], "a": 0, "why": "Larger n lowers the standard error; higher confidence or variability widens the interval.", "losRef": ""}, {"topic": "quant", "q": "A Type II error occurs when an analyst:", "choices": ["rejects a true null", "fails to reject a false null", "accepts a true alternative with certainty"], "a": 1, "why": "Type II error is failing to reject a null hypothesis that is actually false.", "losRef": ""}, {"topic": "quant", "q": "The coefficient of determination in a simple regression measures the proportion of variation in:", "choices": ["X explained by Y", "Y explained by X", "the intercept explained by the slope"], "a": 1, "why": "R-squared is the fraction of dependent-variable variation explained by the regression.", "losRef": ""}, {"topic": "quant", "q": "A bootstrap procedure most directly creates samples by:", "choices": ["resampling with replacement from observed data", "drawing only from a normal distribution", "discarding extreme observations"], "a": 0, "why": "Bootstrap samples are repeatedly drawn with replacement from the observed sample.", "losRef": ""}, {"topic": "quant", "q": "When returns are identical in every period, the arithmetic and geometric means are:", "choices": ["equal", "different by the variance", "opposite in sign"], "a": 0, "why": "With no variation, there is no volatility drag, so the two means coincide.", "losRef": ""}, {"topic": "quant", "q": "A covariance of zero implies that two variables:", "choices": ["are independent in all cases", "have no linear co-movement", "must be normally distributed"], "a": 1, "why": "Zero covariance indicates no linear co-movement, but not necessarily independence.", "losRef": ""}, {"topic": "economics", "q": "A movement along a demand curve is caused by a change in:", "choices": ["the good’s own price", "consumer income", "the price of a substitute"], "a": 0, "why": "A change in the good’s own price changes quantity demanded; other factors shift the curve.", "losRef": ""}, {"topic": "economics", "q": "If supply increases while demand is unchanged, equilibrium price will most likely:", "choices": ["rise", "fall", "remain unchanged"], "a": 1, "why": "A rightward supply shift lowers price and raises equilibrium quantity.", "losRef": ""}, {"topic": "economics", "q": "Marginal cost is best defined as the change in total cost from:", "choices": ["producing one additional unit", "increasing all inputs proportionally", "paying fixed costs"], "a": 0, "why": "Marginal cost is the incremental cost of one more unit of output.", "losRef": ""}, {"topic": "economics", "q": "In a monopoly, marginal revenue is typically:", "choices": ["greater than price", "less than price", "always equal to average cost"], "a": 1, "why": "To sell an extra unit, a monopolist generally lowers price, so marginal revenue is below price.", "losRef": ""}, {"topic": "economics", "q": "The GDP deflator is calculated as:", "choices": ["nominal GDP/real GDP × 100", "real GDP/nominal GDP × 100", "CPI/GDP × 100"], "a": 0, "why": "The GDP deflator compares current-price output with constant-price output.", "losRef": ""}, {"topic": "economics", "q": "Stagflation describes the combination of:", "choices": ["high growth and low inflation", "weak growth and high inflation", "budget surplus and currency appreciation"], "a": 1, "why": "Stagflation combines stagnant or weak output with high inflation.", "losRef": ""}, {"topic": "economics", "q": "A fiscal budget deficit occurs when government:", "choices": ["revenue exceeds spending", "spending exceeds revenue", "exports exceed imports"], "a": 1, "why": "A deficit means expenditures are greater than revenues over the period.", "losRef": ""}, {"topic": "economics", "q": "Under covered interest-rate parity, a currency with the higher interest rate tends to trade at a forward:", "choices": ["premium", "discount", "rate equal to spot"], "a": 1, "why": "The higher-interest-rate currency normally trades at a forward discount relative to the lower-rate currency.", "losRef": ""}, {"topic": "economics", "q": "An automatic stabilizer is best exemplified by:", "choices": ["a newly enacted stimulus package", "progressive income taxes and unemployment benefits", "a central-bank open-market operation"], "a": 1, "why": "These mechanisms change automatically with economic activity without new legislation.", "losRef": ""}, {"topic": "economics", "q": "Comparative advantage is based on lower:", "choices": ["absolute production cost only", "opportunity cost", "market price in every country"], "a": 1, "why": "A party has comparative advantage in the activity with the lower opportunity cost.", "losRef": ""}, {"topic": "corporate", "q": "A project has an initial outlay of 100 and a present value of future cash inflows of 112. Its NPV is:", "choices": ["−12", "12", "212"], "a": 1, "why": "NPV = 112 − 100 = 12.", "losRef": ""}, {"topic": "corporate", "q": "IRR is the discount rate that makes project NPV equal to:", "choices": ["zero", "the initial investment", "the cost of equity"], "a": 0, "why": "IRR solves for the rate at which discounted inflows equal the initial outflow.", "losRef": ""}, {"topic": "corporate", "q": "For a normal project, if IRR exceeds the required return, NPV is most likely:", "choices": ["positive", "negative", "undefined"], "a": 0, "why": "For conventional cash flows, IRR above the hurdle rate implies positive NPV.", "losRef": ""}, {"topic": "corporate", "q": "The cost of retained earnings is most closely related to:", "choices": ["the required return on equity", "the after-tax cost of debt", "the dividend paid last year"], "a": 0, "why": "Retained earnings have an opportunity cost equal to shareholders’ required return.", "losRef": ""}, {"topic": "corporate", "q": "Increasing accounts payable days, all else equal, will most likely:", "choices": ["shorten the cash conversion cycle", "lengthen the cash conversion cycle", "increase inventory turnover"], "a": 0, "why": "Payable days are subtracted in the cash conversion cycle.", "losRef": ""}, {"topic": "corporate", "q": "Financial leverage arises primarily from:", "choices": ["fixed financing costs", "variable operating costs", "higher inventory"], "a": 0, "why": "Debt interest and similar fixed financing obligations magnify equity outcomes.", "losRef": ""}, {"topic": "corporate", "q": "A rights issue gives existing shareholders the opportunity to:", "choices": ["buy new shares, often in proportion to current holdings", "sell company bonds to management", "receive guaranteed dividends"], "a": 0, "why": "Rights offerings allow current owners to maintain proportional ownership by purchasing new shares.", "losRef": ""}, {"topic": "corporate", "q": "A share repurchase, all else equal, reduces:", "choices": ["shares outstanding", "enterprise value by the exact repurchase amount in every case", "operating revenue"], "a": 0, "why": "Repurchased shares normally reduce the number of shares outstanding.", "losRef": ""}, {"topic": "corporate", "q": "A stakeholder-oriented governance model explicitly considers:", "choices": ["only common shareholders", "multiple parties affected by the company", "only senior management"], "a": 1, "why": "Stakeholder governance considers employees, customers, creditors, communities, and owners.", "losRef": ""}, {"topic": "corporate", "q": "A positive externality from a project is a benefit received by:", "choices": ["a third party not fully reflected in market prices", "only the project sponsor", "the tax authority by definition"], "a": 0, "why": "Externalities affect parties outside the direct transaction and may not be fully priced.", "losRef": ""}, {"topic": "fsa", "q": "The accounting equation is:", "choices": ["Assets = Liabilities + Equity", "Revenue = Assets + Expenses", "Cash = Debt + Profit"], "a": 0, "why": "The balance sheet is structured around assets financed by liabilities and owners’ equity.", "losRef": ""}, {"topic": "fsa", "q": "Gross profit equals revenue minus:", "choices": ["cost of goods sold", "operating expenses and tax", "interest expense only"], "a": 0, "why": "Gross profit is sales less the direct cost of goods sold.", "losRef": ""}, {"topic": "fsa", "q": "If ending inventory is overstated, current-period cost of goods sold is most likely:", "choices": ["overstated", "understated", "unchanged"], "a": 1, "why": "COGS = beginning inventory + purchases − ending inventory; overstating ending inventory understates COGS.", "losRef": ""}, {"topic": "fsa", "q": "An increase in an operating liability under the indirect cash-flow method is generally:", "choices": ["added to net income", "subtracted from net income", "classified as investing"], "a": 0, "why": "The company recognized expense without yet paying cash, preserving operating cash.", "losRef": ""}, {"topic": "fsa", "q": "Free cash flow to the firm is cash flow available to:", "choices": ["all capital providers", "common shareholders only", "tax authorities only"], "a": 0, "why": "FCFF is available to debt and equity providers after operating and investment needs.", "losRef": ""}, {"topic": "fsa", "q": "A common-size income statement expresses each line item as a percentage of:", "choices": ["revenue", "total assets", "equity"], "a": 0, "why": "Income-statement common sizing normally uses revenue as the denominator.", "losRef": ""}, {"topic": "fsa", "q": "A common-size balance sheet expresses each item as a percentage of:", "choices": ["total assets", "revenue", "net income"], "a": 0, "why": "Balance-sheet common sizing normally uses total assets.", "losRef": ""}, {"topic": "fsa", "q": "A decline in receivables turnover most likely indicates that collection has become:", "choices": ["faster", "slower", "irrelevant"], "a": 1, "why": "Lower turnover generally means receivables remain outstanding longer.", "losRef": ""}, {"topic": "fsa", "q": "ROA is commonly calculated as net income divided by:", "choices": ["average total assets", "ending revenue", "average current liabilities"], "a": 0, "why": "Using average assets matches the period flow of income with the average resource base.", "losRef": ""}, {"topic": "fsa", "q": "A permanent tax difference affects the effective tax rate but generally does not create a:", "choices": ["deferred tax asset or liability", "current tax expense", "difference between statutory and effective rates"], "a": 0, "why": "Permanent differences never reverse, so they do not create deferred tax balances.", "losRef": ""}, {"topic": "equity", "q": "The bid price is the highest price at which a dealer or investor is willing to:", "choices": ["buy", "sell", "short only"], "a": 0, "why": "The bid is the buying price; the ask is the selling price.", "losRef": ""}, {"topic": "equity", "q": "The bid–ask spread is generally narrower for securities that are:", "choices": ["more liquid", "less frequently traded", "more opaque"], "a": 0, "why": "Greater liquidity and competition usually reduce trading spreads.", "losRef": ""}, {"topic": "equity", "q": "A primary-market transaction occurs when:", "choices": ["an issuer sells newly created securities", "investors trade existing shares", "an index is rebalanced"], "a": 0, "why": "Primary markets provide capital to issuers through new security issuance.", "losRef": ""}, {"topic": "equity", "q": "An equal-weighted index requires periodic rebalancing mainly because:", "choices": ["relative prices change", "all companies issue identical dividends", "market capitalizations never change"], "a": 0, "why": "Price movements alter weights, so the index must trade back to equal weights.", "losRef": ""}, {"topic": "equity", "q": "Fundamental analysis is primarily concerned with estimating:", "choices": ["intrinsic value", "the next trade’s bid–ask spread only", "historical volatility only"], "a": 0, "why": "Fundamental analysis evaluates economic and financial drivers of intrinsic value.", "losRef": ""}, {"topic": "equity", "q": "A firm with sustainable ROE above its required return creates more value when it:", "choices": ["reinvests profitable earnings", "distributes all earnings regardless of opportunities", "increases leverage without limit"], "a": 0, "why": "Reinvestment at returns above the required return adds value.", "losRef": ""}, {"topic": "equity", "q": "A two-stage dividend model is most appropriate when growth is expected to be:", "choices": ["high initially and stable later", "constant forever from today", "negative forever"], "a": 0, "why": "The model captures a finite high-growth stage followed by stable growth.", "losRef": ""}, {"topic": "equity", "q": "Price-to-book is often most informative for firms whose assets are:", "choices": ["measurable and closely related to value", "mostly unrecorded intangible options", "irrelevant to operations"], "a": 0, "why": "Book value is more meaningful when recorded net assets approximate economic capital.", "losRef": ""}, {"topic": "equity", "q": "A cyclical company’s earnings are most likely to be highly sensitive to:", "choices": ["the business cycle", "the day of dividend payment only", "par value"], "a": 0, "why": "Cyclical demand and margins move strongly with economic conditions.", "losRef": ""}, {"topic": "equity", "q": "A research report should clearly distinguish:", "choices": ["facts from opinions", "market prices from trading volume only", "dividends from interest only"], "a": 0, "why": "Clear communication separates factual inputs, assumptions, analysis, and conclusions.", "losRef": ""}, {"topic": "fixed", "q": "A zero-coupon bond pays:", "choices": ["no periodic coupons", "no principal at maturity", "a floating coupon every month"], "a": 0, "why": "It is issued at a discount and pays par at maturity without periodic coupons.", "losRef": ""}, {"topic": "fixed", "q": "A bond trading below par is a:", "choices": ["discount bond", "premium bond", "perpetuity by definition"], "a": 0, "why": "Price below face value means the bond trades at a discount.", "losRef": ""}, {"topic": "fixed", "q": "Yield to maturity assumes coupon cash flows are reinvested at approximately the:", "choices": ["yield to maturity", "coupon rate only", "risk-free rate only"], "a": 0, "why": "The conventional YTM interpretation assumes reinvestment at the YTM.", "losRef": ""}, {"topic": "fixed", "q": "Reinvestment risk is greatest for a bond with:", "choices": ["large interim coupons", "no cash flows before maturity", "a zero coupon"], "a": 0, "why": "More interim cash flows create more exposure to future reinvestment rates.", "losRef": ""}, {"topic": "fixed", "q": "Price risk and reinvestment risk generally move:", "choices": ["in opposite directions as horizon changes", "always in the same direction", "independently of interest rates"], "a": 0, "why": "Rising rates hurt price but improve coupon reinvestment, and vice versa.", "losRef": ""}, {"topic": "fixed", "q": "Macaulay duration is expressed in:", "choices": ["years", "percentage points", "currency units"], "a": 0, "why": "Macaulay duration is a weighted-average time to receipt of cash flows.", "losRef": ""}, {"topic": "fixed", "q": "A putable bond gives the option to:", "choices": ["the investor", "the issuer", "the trustee only"], "a": 0, "why": "The investor may sell the bond back under specified conditions.", "losRef": ""}, {"topic": "fixed", "q": "A senior secured bond generally has expected recovery that is:", "choices": ["higher than a subordinated unsecured bond", "lower than all equity", "exactly 100%"], "a": 0, "why": "Priority and collateral generally improve recovery prospects.", "losRef": ""}, {"topic": "fixed", "q": "A mortgage-backed security investor faces contraction risk when prepayments are:", "choices": ["faster than expected", "slower than expected", "legally prohibited"], "a": 0, "why": "Fast prepayments return principal sooner, shortening the investment horizon.", "losRef": ""}, {"topic": "fixed", "q": "The par curve gives coupon rates that make newly issued bonds price at:", "choices": ["par", "zero", "a deep discount"], "a": 0, "why": "Each par yield is the coupon rate for a bond priced at face value.", "losRef": ""}, {"topic": "derivatives", "q": "The long side of a forward contract agrees to:", "choices": ["buy the underlying at expiration", "sell the underlying at expiration", "pay only an option premium"], "a": 0, "why": "The long commits to purchase at the delivery price.", "losRef": ""}, {"topic": "derivatives", "q": "A short forward gains when the spot price at expiration is:", "choices": ["below the delivery price", "above the delivery price", "equal to the initial spot regardless of K"], "a": 0, "why": "Short-forward payoff is K−ST.", "losRef": ""}, {"topic": "derivatives", "q": "An option’s time value equals option value minus:", "choices": ["intrinsic value", "strike price", "spot price"], "a": 0, "why": "Option premium consists of intrinsic value plus time value.", "losRef": ""}, {"topic": "derivatives", "q": "A call option is out of the money when:", "choices": ["S < X", "S > X", "S = X plus premium"], "a": 0, "why": "Immediate exercise would have no positive value when spot is below strike.", "losRef": ""}, {"topic": "derivatives", "q": "A put option’s value generally increases when the underlying price:", "choices": ["falls", "rises", "becomes equal to zero volatility"], "a": 0, "why": "The right to sell at a fixed strike becomes more valuable as spot declines.", "losRef": ""}, {"topic": "derivatives", "q": "A covered call consists of:", "choices": ["long stock and short call", "short stock and long call", "long put and short bond"], "a": 0, "why": "The stock covers the obligation created by the written call.", "losRef": ""}, {"topic": "derivatives", "q": "A fiduciary call consists of a long call plus:", "choices": ["a risk-free bond paying the strike at expiration", "a short stock position", "a long put"], "a": 0, "why": "The bond supplies the exercise price; together they replicate a protective put.", "losRef": ""}, {"topic": "derivatives", "q": "At initiation, a fairly priced swap has a value closest to:", "choices": ["zero", "the notional amount", "the first payment"], "a": 0, "why": "Terms are set so the present values of the two legs are equal.", "losRef": ""}, {"topic": "derivatives", "q": "Initial margin in futures is best viewed as:", "choices": ["performance collateral", "a down payment on the underlying", "an option premium"], "a": 0, "why": "It secures performance and is adjusted through daily settlement.", "losRef": ""}, {"topic": "derivatives", "q": "Basis is commonly defined as the difference between:", "choices": ["spot and futures prices", "call and put premiums only", "coupon and yield"], "a": 0, "why": "Basis links cash and futures markets and typically converges near expiration.", "losRef": ""}, {"topic": "alternatives", "q": "Private equity investments are generally less liquid than listed equities because they:", "choices": ["lack continuous public trading", "pay no cash flows by definition", "have no legal ownership"], "a": 0, "why": "Private interests are negotiated and do not trade continuously on public exchanges.", "losRef": ""}, {"topic": "alternatives", "q": "A leveraged buyout uses substantial:", "choices": ["debt financing", "central-bank reserves", "commodity inventory only"], "a": 0, "why": "Debt is commonly used to finance the acquisition and amplify equity returns and risk.", "losRef": ""}, {"topic": "alternatives", "q": "Net operating income for property valuation is generally measured before:", "choices": ["financing costs and income tax", "rental revenue", "property operating expenses"], "a": 0, "why": "NOI reflects property operations before capital structure and tax effects.", "losRef": ""}, {"topic": "alternatives", "q": "A hedge fund using long and short positions to reduce broad market exposure is most likely pursuing:", "choices": ["relative-value or equity market-neutral features", "pure long-only indexing", "insured deposit taking"], "a": 0, "why": "Offsetting longs and shorts can reduce market beta while targeting relative mispricing.", "losRef": ""}, {"topic": "alternatives", "q": "A lockup period restricts an investor’s ability to:", "choices": ["redeem capital for a specified period", "receive performance reports", "pay management fees"], "a": 0, "why": "Lockups improve strategy funding stability but reduce investor liquidity.", "losRef": ""}, {"topic": "alternatives", "q": "Contango exists when futures prices are generally:", "choices": ["above spot for later maturities", "below spot for later maturities", "equal to book value"], "a": 0, "why": "An upward-sloping futures curve is commonly described as contango.", "losRef": ""}, {"topic": "alternatives", "q": "For a long-only futures position, negative roll yield commonly occurs in:", "choices": ["contango", "backwardation", "a flat spot market only"], "a": 0, "why": "Rolling from a cheaper expiring contract into a more expensive later contract creates a drag.", "losRef": ""}, {"topic": "alternatives", "q": "Infrastructure revenue may be linked to inflation through:", "choices": ["contractual tariff adjustments", "equity dilution only", "inventory accounting"], "a": 0, "why": "Many regulated or contracted assets include inflation-linked pricing terms.", "losRef": ""}, {"topic": "alternatives", "q": "Operational due diligence focuses most directly on:", "choices": ["processes, controls, service providers, and governance", "only expected market return", "only asset beta"], "a": 0, "why": "Operational failures can cause loss independently of investment strategy.", "losRef": ""}, {"topic": "alternatives", "q": "A digital token’s price may be affected by network adoption, but valuation remains difficult partly because:", "choices": ["cash-flow rights may be unclear or absent", "all tokens pay fixed coupons", "volatility is always zero"], "a": 0, "why": "Many tokens lack conventional contractual cash flows, complicating intrinsic valuation.", "losRef": ""}, {"topic": "portfolio", "q": "The minimum-variance frontier contains portfolios that have the lowest variance for each level of:", "choices": ["expected return", "beta only", "dividend yield"], "a": 0, "why": "It is the lower-risk boundary of feasible portfolios for given expected returns.", "losRef": ""}, {"topic": "portfolio", "q": "The efficient frontier is the portion of the minimum-variance frontier offering:", "choices": ["maximum expected return for a given risk", "minimum return for a given risk", "only risk-free portfolios"], "a": 0, "why": "Efficient portfolios dominate alternatives on the risk–return trade-off.", "losRef": ""}, {"topic": "portfolio", "q": "The capital allocation line combines a risky portfolio with:", "choices": ["a risk-free asset", "only another risky stock", "a commodity future only"], "a": 0, "why": "It represents combinations of the risk-free asset and a selected risky portfolio.", "losRef": ""}, {"topic": "portfolio", "q": "The slope of the capital allocation line is the risky portfolio’s:", "choices": ["Sharpe ratio", "beta", "duration"], "a": 0, "why": "Slope = excess expected return divided by standard deviation.", "losRef": ""}, {"topic": "portfolio", "q": "Unsystematic risk is also called:", "choices": ["idiosyncratic risk", "market risk", "inflation risk"], "a": 0, "why": "It is issuer- or asset-specific and diversifiable.", "losRef": ""}, {"topic": "portfolio", "q": "A risk-averse investor requires higher expected return for:", "choices": ["higher risk", "lower risk", "shorter reports"], "a": 0, "why": "Risk aversion implies compensation is required for accepting more uncertainty.", "losRef": ""}, {"topic": "portfolio", "q": "An endowment with a long horizon and low near-term spending needs may generally have:", "choices": ["greater ability to accept illiquidity", "no need for an IPS", "zero risk capacity"], "a": 0, "why": "Long horizon and limited liquidity demands can support illiquid allocations, subject to other constraints.", "losRef": ""}, {"topic": "portfolio", "q": "Tracking error measures the variability of:", "choices": ["active return relative to a benchmark", "total portfolio return only", "risk-free return"], "a": 0, "why": "It is the standard deviation of portfolio return minus benchmark return.", "losRef": ""}, {"topic": "portfolio", "q": "Value at Risk estimates a loss threshold for a specified:", "choices": ["probability and time horizon", "accounting year only", "coupon rate"], "a": 0, "why": "VaR is conditional on confidence level, horizon, and model assumptions.", "losRef": ""}, {"topic": "portfolio", "q": "Risk budgeting allocates acceptable risk across:", "choices": ["assets, strategies, or managers", "only cash accounts", "historical accounting periods"], "a": 0, "why": "It links total risk tolerance to component risk contributions.", "losRef": ""}, {"topic": "ethics", "q": "A member must maintain independence and objectivity when receiving:", "choices": ["gifts or benefits that could influence judgment", "only salary from the employer", "publicly available data"], "a": 0, "why": "Benefits that could compromise judgment require avoidance, consent, or disclosure as applicable.", "losRef": ""}, {"topic": "ethics", "q": "Plagiarism is a form of:", "choices": ["misrepresentation", "fair dealing", "suitability analysis"], "a": 0, "why": "Presenting another’s work as one’s own misrepresents authorship.", "losRef": ""}, {"topic": "ethics", "q": "Market manipulation includes transactions intended to:", "choices": ["mislead market participants about price or volume", "implement a legitimate client order", "rebalance an index transparently"], "a": 0, "why": "Artificial price or volume signals undermine market integrity.", "losRef": ""}, {"topic": "ethics", "q": "Client confidentiality may generally be broken when:", "choices": ["required by law", "a colleague is curious", "the information could improve marketing"], "a": 0, "why": "Legal requirements can override confidentiality; other limited exceptions may also apply under the Standards.", "losRef": ""}, {"topic": "ethics", "q": "Suitability requires an adviser to consider the client’s:", "choices": ["objectives, constraints, and total portfolio", "favorite security only", "employer’s revenue target"], "a": 0, "why": "Recommendations must fit the client’s circumstances and portfolio context.", "losRef": ""}, {"topic": "ethics", "q": "Priority of transactions generally requires client and employer transactions to take precedence over:", "choices": ["personal transactions", "public market data", "regulatory filings"], "a": 0, "why": "Members should not benefit personally ahead of clients or employers.", "losRef": ""}, {"topic": "ethics", "q": "Referral fees should be disclosed to:", "choices": ["the client or prospective client as appropriate", "no one if legal", "only the referral source"], "a": 0, "why": "Disclosure enables assessment of potential conflicts and cost.", "losRef": ""}, {"topic": "ethics", "q": "Records supporting investment recommendations should generally be maintained by:", "choices": ["the firm or member according to applicable duties and policy", "the issuer only", "the exchange only"], "a": 0, "why": "Adequate records support diligence, communication, and supervision.", "losRef": ""}, {"topic": "ethics", "q": "A member who suspects a colleague violated the law should first avoid:", "choices": ["participating in or assisting the violation", "documenting concerns", "seeking appropriate guidance"], "a": 0, "why": "The member must dissociate from illegal or unethical activity and take appropriate steps.", "losRef": ""}, {"topic": "ethics", "q": "Using the CFA designation as a noun to imply a superior type of person is:", "choices": ["improper use of the designation", "required marketing", "acceptable if performance is strong"], "a": 0, "why": "The designation must be used as an adjective and not exaggerated or misrepresented.", "losRef": ""}, {"topic": "fsa", "q": "The first step in a financial statement analysis framework is to:", "choices": ["calculate ratios", "define the purpose and context", "adjust accounting data"], "a": 1, "why": "The analytical question, audience, horizon, and context determine the data and methods required.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Which source most likely explains significant accounting estimates and commitments?", "choices": ["Financial statement notes", "Share-price chart", "Marketing brochure"], "a": 0, "why": "Notes provide policy, estimate, commitment, contingency, and risk details.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "An unmodified audit opinion most directly indicates that the statements:", "choices": ["guarantee future solvency", "are presented fairly in material respects under the framework", "contain no fraud of any size"], "a": 1, "why": "The opinion provides reasonable assurance about fair presentation, not guarantees of performance or complete fraud absence.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "For short-term credit analysis, the most relevant emphasis is usually:", "choices": ["brand value over 20 years", "liquidity and near-term debt service", "long-run equity terminal value"], "a": 1, "why": "A short-term lender focuses on cash availability and repayment capacity.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Management commentary is particularly useful for understanding:", "choices": ["strategy and management's view of drivers", "the independent audit opinion", "only historical tax payments"], "a": 0, "why": "Management commentary discusses strategy, risks, trends, and outlook, though it may be biased.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "When two firms apply different acceptable accounting policies, an analyst should most appropriately:", "choices": ["ignore the difference", "consider transparent comparability adjustments", "replace both statements with market prices"], "a": 1, "why": "Policy differences can distort comparisons and may require supported adjustments.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Which is an external information source?", "choices": ["Competitor regulatory filing", "The company's balance sheet", "The company's footnotes"], "a": 0, "why": "A competitor filing is external to the analyzed company.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "A qualified audit opinion should cause the analyst to:", "choices": ["automatically value equity at zero", "understand the scope and financial effect of the qualification", "ignore all remaining disclosures"], "a": 1, "why": "The nature and materiality of the issue must be assessed.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "The follow-up step in analysis primarily involves:", "choices": ["monitoring changes and updating conclusions", "deleting prior assumptions", "stopping after report delivery"], "a": 0, "why": "Analysis is ongoing as new information becomes available.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Regulatory filings can be more useful than a glossy annual report because they often contain:", "choices": ["required standardized disclosures", "guaranteed forecasts", "only advertising"], "a": 0, "why": "Regulatory filings provide mandated and often detailed information.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "A key limitation of ratio analysis is that ratios:", "choices": ["never permit comparisons", "can be affected by accounting policies and business models", "are always based on cash"], "a": 1, "why": "Ratios require context and comparability assessment.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "The analytical process should be documented primarily to:", "choices": ["support consistency and defensible conclusions", "hide assumptions", "avoid future updates"], "a": 0, "why": "Documentation improves reproducibility, review, and accountability.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Key audit matters most appropriately:", "choices": ["identify areas of significant audit attention", "replace the notes", "predict bankruptcy"], "a": 0, "why": "They highlight significant judgment areas but are not predictions.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Which action belongs to processing data?", "choices": ["Reclassifying items for comparability", "Defining the decision question", "Presenting the final recommendation"], "a": 0, "why": "Processing includes organizing, calculating, and adjusting data.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Industry data are most useful for:", "choices": ["providing context and peer benchmarks", "proving management fraud", "eliminating accounting differences"], "a": 0, "why": "Industry data help assess relative performance and structural norms.", "module": 0, "difficulty": "medium"}, {"topic": "fsa", "q": "Revenue recognized before cash collection most directly increases:", "choices": ["revenue and a receivable or contract asset", "cash and debt", "inventory and dividends"], "a": 0, "why": "Credit revenue creates an asset until collection.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Capitalizing an eligible cost instead of expensing it immediately initially causes profit to be:", "choices": ["higher", "lower", "unchanged in all cases"], "a": 0, "why": "Capitalization defers expense recognition.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Basic EPS denominator uses:", "choices": ["ending common shares", "weighted-average common shares", "authorized shares"], "a": 1, "why": "Weighted average reflects shares outstanding during the period.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Antidilutive securities are:", "choices": ["included in diluted EPS", "excluded from diluted EPS", "included in basic EPS denominator"], "a": 1, "why": "Including them would increase EPS or reduce loss per share, so they are excluded.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "A common-size income statement normally expresses items as a percentage of:", "choices": ["total assets", "revenue", "equity"], "a": 1, "why": "Revenue is the standard base.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Gross margin is calculated as:", "choices": ["gross profit/revenue", "operating profit/assets", "net income/equity"], "a": 0, "why": "Gross margin measures gross profit per unit of revenue.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "A gain on sale of equipment should be assessed as:", "choices": ["necessarily recurring operating revenue", "potentially nonrecurring and nonoperating", "a financing cash inflow"], "a": 1, "why": "It is generally not a core revenue source and its cash proceeds are investing.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Expensing a cost immediately compared with capitalization initially results in:", "choices": ["lower assets and lower profit", "higher assets and lower profit", "lower liabilities and higher profit"], "a": 0, "why": "The expense reduces profit and no asset is recognized.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "If revenue grows 8% and receivables grow 30%, an analyst should most likely investigate:", "choices": ["collection and revenue-recognition quality", "debt maturity only", "share repurchases only"], "a": 0, "why": "Receivables growing much faster than sales can signal weaker collection or aggressive recognition.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Net margin includes the effects of:", "choices": ["only production costs", "operating, financing, nonoperating, and tax items", "only dividends"], "a": 1, "why": "Net income reflects the full income statement.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "A restructuring charge described as 'one-time' should be removed from normalized earnings:", "choices": ["automatically", "only after assessing recurrence and economic relevance", "never"], "a": 1, "why": "Some firms repeatedly incur restructuring costs.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Diluted EPS is generally:", "choices": ["greater than or equal to basic EPS", "less than or equal to basic EPS for profitable firms", "unrelated to potential shares"], "a": 1, "why": "Dilutive securities reduce EPS; antidilutive instruments are excluded.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "If weighted-average shares rise while income available to common is unchanged, basic EPS:", "choices": ["rises", "falls", "is unchanged"], "a": 1, "why": "The denominator increases.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "An impairment charge most directly causes current profit and assets to:", "choices": ["increase", "decrease", "remain unchanged"], "a": 1, "why": "The asset is written down and a loss is recognized.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Operating margin differs from gross margin because operating margin also reflects:", "choices": ["operating expenses", "dividends", "share issuance"], "a": 0, "why": "Operating profit subtracts operating costs beyond COGS.", "module": 1, "difficulty": "medium"}, {"topic": "fsa", "q": "Goodwill is most commonly created by:", "choices": ["organic advertising", "a business combination", "paying a dividend"], "a": 1, "why": "Goodwill arises when acquisition consideration exceeds recognized identifiable net assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A finite-lived intangible asset is generally:", "choices": ["amortized over its useful life", "never expensed", "recorded as revenue"], "a": 0, "why": "Finite-lived intangibles are amortized and tested for impairment as applicable.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A large goodwill balance relative to equity most likely indicates:", "choices": ["significant acquisition-related asset exposure", "high cash holdings", "no impairment risk"], "a": 0, "why": "Goodwill reflects acquisition premiums and can expose equity to impairment.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "The quick ratio differs from the current ratio mainly by excluding:", "choices": ["cash", "inventory", "current liabilities"], "a": 1, "why": "Quick assets generally exclude inventory and sometimes other less-liquid current assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A receivables balance growing faster than revenue may indicate:", "choices": ["improving cash collection", "potential collection or recognition concerns", "lower credit sales"], "a": 1, "why": "The relationship can signal slower collections or aggressive revenue recognition.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A debt maturity schedule is important primarily for assessing:", "choices": ["refinancing and liquidity risk", "gross margin", "inventory obsolescence"], "a": 0, "why": "Concentrated near-term maturities can create funding pressure.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Internally generated brand value is often:", "choices": ["fully recognized at market value", "not recognized even though economically valuable", "classified as cash"], "a": 1, "why": "Recognition rules can omit internally generated economic assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Book value of equity is best described as:", "choices": ["always equal to market capitalization", "an accounting residual that may differ materially from market value", "the present value of all dividends"], "a": 1, "why": "Book and market values use different measurement bases.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "An increase in the allowance for doubtful accounts most directly:", "choices": ["reduces net receivables", "increases cash", "reduces debt"], "a": 0, "why": "The contra-asset lowers receivables' carrying amount.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Fair-value measurement generally makes reported amounts more sensitive to:", "choices": ["current market assumptions", "historical payroll only", "authorized shares"], "a": 0, "why": "Fair value reflects market-based inputs and valuation estimates.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Noncurrent liabilities include obligations such as:", "choices": ["long-term debt and pension obligations", "cash and inventory", "revenue and COGS"], "a": 0, "why": "They are obligations due beyond the current classification period.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "If current assets are 300 and current liabilities 200, the current ratio is:", "choices": ["0.67", "1.50", "2.00"], "a": 1, "why": "300/200 = 1.50.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "If an acquisition price is 450 and identifiable net assets are 390, goodwill is:", "choices": ["60", "390", "840"], "a": 0, "why": "450−390 = 60.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "A common-size increase in debt from 25% to 40% of assets most directly suggests:", "choices": ["greater balance-sheet leverage", "lower revenue", "higher inventory turnover"], "a": 0, "why": "Debt finances a larger share of assets.", "module": 2, "difficulty": "medium"}, {"topic": "fsa", "q": "Under the indirect method, an increase in inventory is:", "choices": ["added to net income", "subtracted from net income", "classified as financing"], "a": 1, "why": "An operating asset increase uses cash.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Under the indirect method, an increase in accounts payable is:", "choices": ["added to net income", "subtracted from net income", "ignored"], "a": 0, "why": "An operating liability increase preserves cash.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Depreciation is added back to net income because it is:", "choices": ["a noncash expense", "an investing inflow", "a financing outflow"], "a": 0, "why": "It reduced profit without current cash use.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "A gain on sale of equipment is subtracted in indirect CFO because:", "choices": ["sale proceeds belong in investing and the gain increased net income", "it reduced net income", "it is a financing item"], "a": 0, "why": "The gain must be removed from CFO to avoid double counting.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "The direct method reports:", "choices": ["cash collected and cash paid by major operating category", "only net income adjustments", "only financing flows"], "a": 0, "why": "It presents gross operating cash receipts and payments.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Correctly prepared direct and indirect methods produce CFO that is:", "choices": ["different", "the same", "always zero"], "a": 1, "why": "Only presentation differs.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Buying equipment for cash is classified as:", "choices": ["operating", "investing", "financing"], "a": 1, "why": "It is acquisition of a long-term asset.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Issuing common shares for cash is classified as:", "choices": ["operating", "investing", "financing"], "a": 2, "why": "It is a transaction with capital providers.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Cash collected from customers equals sales adjusted for the change in:", "choices": ["receivables", "debt", "PPE"], "a": 0, "why": "Credit sales not collected remain in receivables.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "If receivables decrease, cash collected from customers is generally:", "choices": ["less than sales", "greater than sales", "equal to zero"], "a": 1, "why": "Collections include prior-period receivables.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "If inventory increases and payables are unchanged, cash paid to suppliers is generally:", "choices": ["less than COGS", "greater than COGS", "equal to dividends"], "a": 1, "why": "Purchases exceed COGS when inventory builds.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Under US GAAP, dividends paid are generally classified as:", "choices": ["operating", "investing", "financing"], "a": 2, "why": "US GAAP classifies dividends paid as financing.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "Under IFRS, classification of interest paid may be:", "choices": ["operating or financing, applied consistently", "investing only", "never disclosed"], "a": 0, "why": "IFRS permits a policy choice under the applicable rules.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "A decrease in an operating liability is an indirect CFO adjustment that is:", "choices": ["positive", "negative", "always noncash"], "a": 1, "why": "Paying down the liability uses cash.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "The cash-flow statement reconciles:", "choices": ["beginning and ending cash", "beginning and ending revenue", "gross and net margin"], "a": 0, "why": "It explains the period's cash change.", "module": 3, "difficulty": "medium"}, {"topic": "fsa", "q": "FCFF represents cash available to:", "choices": ["common equity only", "all capital providers", "employees only"], "a": 1, "why": "FCFF is available to debt and equity capital providers.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "FCFE represents cash available to:", "choices": ["common equity after investment and net borrowing", "all creditors before tax", "suppliers only"], "a": 0, "why": "FCFE is the residual available to common equity.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "When deriving FCFF from CFO and interest is included in CFO, add back:", "choices": ["after-tax interest", "full debt principal", "dividends"], "a": 0, "why": "Interest is added after tax because FCFF is pre-financing but after-tax.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "Net borrowing equals:", "choices": ["debt issued minus debt repaid", "interest minus tax", "CFO minus revenue"], "a": 0, "why": "It measures net new debt financing.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "A persistent excess of net income over CFO may warrant concern about:", "choices": ["earnings cash conversion", "share authorization", "only tax rates"], "a": 0, "why": "Sustained accrual build-up may weaken earnings quality.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "CFO margin is:", "choices": ["CFO/revenue", "CFO/assets only", "revenue/CFO"], "a": 0, "why": "It measures operating cash generated per unit of revenue.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "Negative investing cash flow caused by productive capital expenditure is:", "choices": ["automatically bad", "not automatically bad", "always financing"], "a": 1, "why": "Investment may support growth and future cash flow.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If CFO is 300 and capex 120, before financing adjustments cash after capex is:", "choices": ["180", "420", "120"], "a": 0, "why": "300−120 = 180.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If debt issued is 80 and repaid is 50, net borrowing is:", "choices": ["30", "130", "−30"], "a": 0, "why": "80−50 = 30.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If CFO is 200, capex 70, and net borrowing 20, FCFE is:", "choices": ["110", "150", "290"], "a": 1, "why": "200−70+20 = 150.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "If CFO is 200, after-tax interest 15, and capex 70, FCFF is:", "choices": ["115", "145", "285"], "a": 1, "why": "200+15−70 = 145.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "Common-size cash-flow analysis most often scales cash flows by:", "choices": ["revenue or another consistent base", "authorized shares only", "the audit fee"], "a": 0, "why": "A consistent base reveals structural trends.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "CFO-to-debt is primarily a measure of:", "choices": ["cash debt-servicing capacity", "gross profitability", "inventory age"], "a": 0, "why": "It relates operating cash generation to debt obligations.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "A rising CFO margin with stable revenue most likely indicates:", "choices": ["improved operating cash generation", "lower cash generation", "automatic fraud"], "a": 0, "why": "More cash is generated per unit of revenue.", "module": 4, "difficulty": "medium"}, {"topic": "fsa", "q": "FCFF and FCFE calculations should be interpreted carefully because:", "choices": ["classification and starting-point definitions can differ", "cash flow is never useful", "taxes do not matter"], "a": 0, "why": "The exact formula depends on the available data and classification choices.", "module": 4, "difficulty": "medium"}], "formulas": [["Geometric return", "[(Ending value / Beginning value)^(1/n)] − 1"], ["Present value", "PV = FV / (1 + r)^n"], ["Growing perpetuity", "PV = C1 / (r − g), where r > g"], ["Portfolio expected return", "E(Rp) = Σ wiE(Ri)"], ["Two-asset variance", "w1²σ1² + w2²σ2² + 2w1w2Cov12"], ["CAPM", "E(Ri) = Rf + βi[E(Rm) − Rf]"], ["WACC", "wd rd(1−t) + wp rp + we re"], ["Gordon growth", "V0 = D1 / (r − g)"], ["Long forward payoff", "ST − K"], ["European put–call parity", "c + PV(X) = p + S0 (non-dividend-paying asset)"]], "guides": {"quant": {"overview": "Quantitative Methods supplies the mathematical language used throughout Level I. Focus first on cash-flow timing, return measurement, probability, sampling, estimation, hypothesis testing, regression, simulation, and interpreting model output. Do not merely memorize equations: identify what each variable means, the assumptions behind the method, and how a change in an input affects the result.", "workflow": ["Draw a cash-flow timeline before using a formula or calculator.", "Write the units: annual, monthly, percentage, decimal, population, or sample.", "Estimate the direction and approximate size before calculating.", "Check whether the question asks for a population parameter, sample statistic, test decision, or forecast."], "formulas": [["Compound value", "FV = PV(1+r)^n"], ["Present value", "PV = FV/(1+r)^n"], ["Geometric mean", "[(1+R1)…(1+Rn)]^(1/n) − 1"], ["Standard error of mean", "s/√n"], ["Test statistic", "(estimate − hypothesized value)/standard error"], ["Simple regression", "Yi = b0 + b1Xi + εi"]], "traps": ["Using an arithmetic mean for a compounded multi-period growth rate.", "Mixing annual and periodic rates.", "Interpreting failure to reject as proof that the null is true.", "Treating correlation as causation.", "Ignoring assumptions or sample-selection bias."]}, "economics": {"overview": "Economics questions test how households, firms, governments, central banks, and currency markets respond to incentives and constraints. Build a clear cause-and-effect chain: what shifts, which curve moves, how equilibrium changes, and whether the result is nominal or real. For macroeconomics, connect growth, inflation, unemployment, policy, interest rates, and exchange rates.", "workflow": ["Identify the market and the variable held constant.", "Separate a curve shift from movement along a curve.", "State the initial equilibrium and the direction of the shock.", "For policy questions, distinguish objective, instrument, transmission mechanism, and possible limitation."], "formulas": [["Price elasticity of demand", "%Δ quantity demanded / %Δ price"], ["GDP expenditure approach", "C + I + G + (X−M)"], ["Real interest rate approximation", "Nominal rate − expected inflation"], ["Forward FX relation concept", "Forward premium/discount reflects interest-rate differential under covered parity"]], "traps": ["Confusing changes in demand with changes in quantity demanded.", "Assuming a policy works instantly or without expectations.", "Mixing nominal GDP growth with real output growth.", "Reversing base and price currencies in FX quotes."]}, "corporate": {"overview": "Corporate Finance links governance, investment decisions, financing decisions, liquidity, and value creation. The central principle is incremental after-tax cash flow discounted at a rate appropriate for its risk. Learn why NPV is the preferred decision rule, how financing mix affects the cost of capital, and how working-capital choices affect liquidity and profitability.", "workflow": ["Use incremental cash flows only.", "Include opportunity costs and side effects; exclude sunk costs.", "Match project risk with the discount rate.", "Check whether a ratio change improves liquidity at the expense of profitability or vice versa."], "formulas": [["NPV", "Σ CFt/(1+r)^t − initial investment"], ["WACC", "wd rd(1−T) + wp rp + we re"], ["Cash conversion cycle", "Inventory days + Receivable days − Payable days"], ["Degree of operating leverage", "%Δ operating profit / %Δ sales"]], "traps": ["Using accounting profit instead of cash flow.", "Discounting all projects at the company WACC regardless of risk.", "Including sunk costs.", "Assuming more debt always lowers WACC.", "Treating a shorter cash cycle as automatically good without considering operations."]}, "fsa": {"overview": "Financial Statement Analysis is a high-weight area. Learn how transactions flow through the income statement, balance sheet, cash-flow statement, and equity. Then analyze how accounting choices affect reported performance, cash flow, ratios, comparability, and earnings quality. Always distinguish an economic event from its accounting presentation.", "workflow": ["Identify the transaction and affected accounts.", "Trace its effect on profit, assets, liabilities, equity, and cash flow.", "Determine whether the difference is timing, classification, measurement, or disclosure.", "Recalculate ratios and explain the economic interpretation."], "formulas": [["Basic EPS", "(Net income − preferred dividends)/weighted-average common shares"], ["Current ratio", "Current assets/current liabilities"], ["Inventory turnover", "COGS/average inventory"], ["ROE", "Net income/average equity"], ["CFO indirect starting point", "Net income + noncash charges − operating asset increases + operating liability increases"]], "traps": ["Equating net income with cash generated.", "Ignoring average balance-sheet values in turnover ratios.", "Assuming an unmodified audit opinion guarantees financial health.", "Comparing ratios without adjusting for accounting policy differences.", "Confusing temporary and permanent tax differences."]}, "equity": {"overview": "Equity Investments combines market structure, indexes, efficiency, industry and company analysis, forecasting, and valuation. A valuation conclusion is only as sound as its assumptions. Separate the operating forecast from the discount rate, and connect competitive position, growth, margins, reinvestment, risk, and terminal value.", "workflow": ["Define the business and source of cash flows.", "Analyze industry structure and competitive advantage.", "Forecast revenue, margins, investment, and financing consistently.", "Select a valuation method appropriate to the company and available data.", "Stress-test growth, margins, and required return."], "formulas": [["Gordon growth model", "V0 = D1/(r−g), r>g"], ["Holding-period return", "(P1−P0+D1)/P0"], ["Market-cap index weight", "Company market cap/total index market cap"], ["Justified leading P/E concept", "Payout ratio/(r−g)"]], "traps": ["Using an unsustainable growth rate in a perpetual model.", "Treating a low P/E as proof of undervaluation.", "Ignoring dilution or capital needs.", "Confusing enterprise value with equity value.", "Using scenario probabilities that do not sum to 100%."]}, "fixed": {"overview": "Fixed Income questions require disciplined cash-flow valuation. Start with bond features and promised cash flows, then discount them using the appropriate curve. Understand yield measures, term structure, duration, convexity, embedded options, credit risk, and securitization. Always ask who owns the option and how a change in rates affects expected cash flows.", "workflow": ["Map every contractual cash flow.", "Identify whether the bond has an embedded option.", "Choose the correct yield or spot rates.", "Estimate direction using price–yield logic, then calculate.", "Separate interest-rate risk, reinvestment risk, liquidity risk, and credit risk."], "formulas": [["Bond price", "Σ CFt/(1+rt)^t"], ["Current yield", "Annual coupon/current price"], ["Approximate duration effect", "%ΔP ≈ −Modified duration × Δy"], ["Expected credit loss", "Probability of default × loss given default × exposure"]], "traps": ["Using coupon rate as the discount rate.", "Forgetting that price and yield move inversely.", "Applying plain duration to a bond whose cash flows change materially with rates.", "Confusing spread widening with falling required return.", "Assuming securitization removes the pool's risk."]}, "derivatives": {"overview": "Derivatives transfer or reshape risk. Master the payoff at expiration before studying value before expiration. Distinguish forwards, futures, swaps, calls, and puts; identify the long and short sides; and use no-arbitrage and replication. Options are asymmetric: the buyer has a right, while the writer has an obligation.", "workflow": ["Draw the payoff at expiration.", "Identify long versus short and right versus obligation.", "Separate payoff from profit by considering the initial premium.", "Use replication or put–call parity to check prices.", "State the effect of underlying price, volatility, time, rates, and income."], "formulas": [["Long forward payoff", "ST−K"], ["Long call payoff", "max(0, ST−X)"], ["Long put payoff", "max(0, X−ST)"], ["European put–call parity", "c + PV(X) = p + S0 for a non-dividend-paying asset"]], "traps": ["Calling an option payoff a profit without subtracting premium.", "Treating a forward as having limited downside.", "Confusing futures daily settlement with final payoff.", "Reversing put–call parity terms.", "Assuming option value can be negative to its holder."]}, "alternatives": {"overview": "Alternative Investments include private capital, real estate, infrastructure, commodities, hedge funds, and digital assets. Questions emphasize distinctive cash flows, leverage, illiquidity, valuation uncertainty, fees, governance, and data biases. Reported volatility may understate economic risk when prices are infrequent or model-based.", "workflow": ["Identify the return source and underlying economic exposure.", "Assess leverage, liquidity, valuation method, and fee structure.", "Check index and performance-reporting biases.", "Distinguish direct ownership from fund or derivative exposure.", "Review operational, legal, custody, and counterparty risks."], "formulas": [["Simple income capitalization", "Property value = NOI/capitalization rate"], ["Commodity futures total-return components", "Spot return + roll yield + collateral yield"], ["Private investment multiple", "Distributions and residual value / paid-in capital (concept varies by metric)"]], "traps": ["Comparing smoothed appraisal returns directly with traded-asset volatility.", "Ignoring carried interest and management fees.", "Treating every hedge-fund strategy as market neutral.", "Assuming illiquidity means low risk.", "Ignoring custody and operational risks for digital assets."]}, "portfolio": {"overview": "Portfolio Construction integrates risk, return, diversification, investor objectives, constraints, asset allocation, and risk management. The key insight is that portfolio risk depends on covariance, not only the risk of each asset. A suitable portfolio must reflect both willingness and ability to take risk, with the lower normally limiting.", "workflow": ["Define measurable return and risk objectives.", "List liquidity, horizon, tax, legal, and special constraints.", "Estimate expected returns, risks, and correlations consistently.", "Construct and evaluate portfolios in total, not security by security.", "Monitor, rebalance, and document changes."], "formulas": [["Portfolio expected return", "Σ wiE(Ri)"], ["Two-asset variance", "w1²σ1²+w2²σ2²+2w1w2ρ12σ1σ2"], ["CAPM", "E(Ri)=Rf+βi[E(Rm)−Rf]"], ["Sharpe ratio", "(Portfolio return−risk-free rate)/portfolio standard deviation"]], "traps": ["Assuming more securities always means better diversification.", "Using total volatility instead of beta in CAPM.", "Ignoring liabilities and liquidity needs.", "Treating willingness as the only measure of risk tolerance.", "Rebalancing without considering costs and taxes."]}, "ethics": {"overview": "Ethics is tested through facts and conduct, not through slogans. Read the vignette carefully, identify the applicable duty, determine what the person knew or should have known, and select the action that best protects market integrity, clients, and the profession. Learn the Standards and apply them consistently, especially where conflicts, material nonpublic information, diligence, suitability, performance, and disclosure are involved.", "workflow": ["Identify the actor, client, employer, and affected market participants.", "Separate facts from assumptions.", "Identify the applicable law, code, or standard.", "Choose the stricter applicable requirement unless following it would violate law.", "Prefer prevention, disclosure, documentation, and escalation over silence."], "formulas": [], "traps": ["Assuming disclosure cures every conflict.", "Using material nonpublic information within mosaic analysis.", "Believing fair dealing requires simultaneous communication in every operational case.", "Guaranteeing returns or overstating performance.", "Failing to distinguish preparation to leave an employer from solicitation or misappropriation."]}}, "workedExamples": {"quant": [{"title": "Compound annual growth", "problem": "An investment rises from 80 to 100 over three years. Find the annual compound return.", "steps": ["Compute the growth multiple: 100/80 = 1.25.", "Take the cube root: 1.25^(1/3) ≈ 1.0772.", "Subtract 1."], "answer": "Approximately 7.72% per year.", "trap": "Do not divide the total 25% gain by three; compounding is nonlinear."}, {"title": "Hypothesis-test decision", "problem": "A two-sided test uses a 5% significance level and produces p = 0.032. What is the decision?", "steps": ["Compare p-value with α.", "0.032 < 0.05.", "Reject the null hypothesis."], "answer": "Reject H0 at the 5% level.", "trap": "This does not prove the alternative with certainty; it indicates the sample is sufficiently inconsistent with H0."}], "economics": [{"title": "Elastic demand and revenue", "problem": "Price rises by 5% and quantity demanded falls by 12%. What happens to total revenue?", "steps": ["Elasticity magnitude = 12%/5% = 2.4.", "Demand is elastic because the magnitude exceeds 1.", "Quantity falls proportionally more than price rises."], "answer": "Total revenue decreases.", "trap": "Use absolute elasticity when classifying elasticity."}, {"title": "Real interest rate", "problem": "A nominal interest rate is 6% and expected inflation is 2%. Estimate the real rate.", "steps": ["Use the approximation: nominal − expected inflation.", "6% − 2% = 4%."], "answer": "Approximately 4%.", "trap": "The exact Fisher relation gives a slightly different result."}], "corporate": [{"title": "Project NPV", "problem": "A project costs 100 today and pays 60 in one year and 60 in two years. Required return is 10%.", "steps": ["PV year 1 = 60/1.10 = 54.55.", "PV year 2 = 60/1.10² = 49.59.", "Total PV = 104.14.", "NPV = 104.14 − 100."], "answer": "NPV ≈ 4.14; accept if independent.", "trap": "Do not subtract financing interest from project cash flows when discounting at WACC."}, {"title": "Cash conversion cycle", "problem": "Inventory days are 45, receivable days 30, and payable days 25.", "steps": ["CCC = inventory days + receivable days − payable days.", "45 + 30 − 25 = 50."], "answer": "Cash conversion cycle = 50 days.", "trap": "Payable days are subtracted because supplier financing delays cash outflow."}], "fsa": [{"title": "Indirect CFO adjustment", "problem": "Net income is 120, depreciation is 20, and accounts receivable increases by 15.", "steps": ["Start with net income: 120.", "Add back noncash depreciation: +20.", "Subtract increase in receivables: −15."], "answer": "CFO before other adjustments = 125.", "trap": "An increase in an operating asset is a use of cash."}, {"title": "Inventory turnover", "problem": "COGS is 500, beginning inventory 90, ending inventory 110.", "steps": ["Average inventory = (90+110)/2 = 100.", "Turnover = 500/100."], "answer": "Inventory turnover = 5.0 times.", "trap": "Use average inventory when the denominator is a balance-sheet account measured over a period."}], "equity": [{"title": "Gordon growth valuation", "problem": "Next dividend is 3.00, required return 10%, perpetual growth 4%.", "steps": ["Use V0 = D1/(r−g).", "Denominator = 0.10−0.04 = 0.06.", "3/0.06 = 50."], "answer": "Estimated value = 50.", "trap": "The growth rate must be sustainable and below the required return."}, {"title": "Holding-period return", "problem": "A share is bought for 40, sold for 44, and pays a dividend of 1.", "steps": ["Price gain = 44−40 = 4.", "Total gain = 4+1 = 5.", "Return = 5/40."], "answer": "Holding-period return = 12.5%.", "trap": "Include distributions received during the holding period."}], "fixed": [{"title": "Duration estimate", "problem": "Modified duration is 5.2 and yield rises by 0.40%. Estimate the price change.", "steps": ["Convert yield change to decimal: 0.004.", "Approximate %ΔP = −5.2×0.004.", "= −0.0208."], "answer": "Price falls approximately 2.08%.", "trap": "Duration is a first-order estimate and is less precise for large yield changes."}, {"title": "Expected credit loss", "problem": "PD is 3%, recovery rate 40%, and exposure is 1,000,000.", "steps": ["LGD = 1−0.40 = 0.60.", "Expected loss = 0.03×0.60×1,000,000."], "answer": "Expected credit loss = 18,000.", "trap": "Do not multiply by recovery rate; use loss given default."}], "derivatives": [{"title": "Long call profit", "problem": "Call strike is 50, premium is 4, and expiration price is 58.", "steps": ["Payoff = max(0,58−50)=8.", "Profit = payoff−premium = 8−4."], "answer": "Profit = 4.", "trap": "Payoff and profit are not the same."}, {"title": "Long forward payoff", "problem": "Delivery price is 75 and expiration spot price is 69.", "steps": ["Long-forward payoff = ST−K.", "69−75 = −6."], "answer": "Loss of 6 per unit.", "trap": "Forward downside is not limited to an initial premium."}], "alternatives": [{"title": "Property capitalization", "problem": "A property has NOI of 900,000 and a capitalization rate of 7.5%.", "steps": ["Value = NOI/cap rate.", "900,000/0.075 = 12,000,000."], "answer": "Estimated property value = 12 million.", "trap": "Use stabilized NOI consistent with the selected cap rate."}, {"title": "Commodity futures return", "problem": "Spot return is 5%, roll yield −2%, collateral yield 3%.", "steps": ["Add the three conceptual components.", "5%−2%+3%."], "answer": "Approximate total return = 6%.", "trap": "Futures performance can differ materially from spot-price performance."}], "portfolio": [{"title": "Portfolio expected return", "problem": "A portfolio invests 60% in an asset expected to return 8% and 40% in one expected to return 4%.", "steps": ["Multiply each return by its weight.", "0.60×8% + 0.40×4%.", "4.8%+1.6%."], "answer": "Expected portfolio return = 6.4%.", "trap": "Expected return is a weighted average; portfolio risk is not."}, {"title": "CAPM required return", "problem": "Risk-free rate is 3%, beta 1.2, and market risk premium 5%.", "steps": ["Use Rf+β×market risk premium.", "3%+1.2×5%.", "3%+6%."], "answer": "Required return = 9%.", "trap": "Use market risk premium, not expected market return, in the multiplication term."}], "ethics": [{"title": "Material nonpublic information", "problem": "An analyst learns privately that a listed company will lose its largest customer. The information is likely price-sensitive.", "steps": ["Assess materiality: likely to affect investor decisions or price.", "Assess public status: it was learned privately.", "Do not trade, recommend, or cause others to trade."], "answer": "Treat it as material nonpublic information and refrain from acting.", "trap": "Disclosure to a supervisor does not make the information public."}, {"title": "Conflict disclosure", "problem": "An analyst owns shares in a company being recommended to clients.", "steps": ["Identify the conflict.", "Disclose it prominently before clients rely on the recommendation.", "Maintain objective and independent analysis."], "answer": "Prominent disclosure is required; additional controls may also be appropriate.", "trap": "Disclosure does not excuse biased research or inadequate diligence."}]}, "fsaLessons": {"0": {"title": "Introduction to Financial Statement Analysis", "summary": "Financial statement analysis converts reported information into judgments about performance, financial position, cash-generation ability, risk, and value. A disciplined analyst defines the purpose, gathers reliable information, adjusts for comparability, analyzes relationships and trends, interprets the results, communicates conclusions, and monitors changes.", "mustKnow": ["The six-step framework: define purpose and context; collect data; process data; analyze and interpret; develop and communicate conclusions; follow up.", "Financial statements are only one source. Notes, management commentary, regulatory filings, earnings calls, industry data, credit reports, and macroeconomic information can materially change the conclusion.", "An audit opinion provides assurance about conformity with the reporting framework; it does not guarantee profitability, solvency, or absence of all fraud.", "Accounting standards influence recognition, measurement, presentation, and disclosure. Comparability may require analyst adjustments."], "detailed": [{"heading": "Purpose and context", "text": "Begin with a precise question. Equity analysis may focus on sustainable earnings and valuation; credit analysis may focus on liquidity, leverage, covenant capacity, and downside protection. The time horizon, benchmark, and required level of detail determine which data and tools are appropriate."}, {"heading": "Information hierarchy", "text": "Primary statements provide structured totals, but notes often explain accounting policies, estimates, segment data, commitments, contingencies, maturity schedules, and risks. Management commentary provides strategy and outlook but may contain optimistic bias. External sources help test management’s narrative."}, {"heading": "Audit reports", "text": "An unmodified opinion means the statements are presented fairly in material respects under the applicable framework. Qualified, adverse, or disclaimer opinions require close attention. Key audit matters can identify areas involving significant judgment, but they do not replace independent analysis."}, {"heading": "Analyst adjustments", "text": "When firms use different policies or classifications, an analyst may restate items to improve comparability. Adjustments should be transparent, internally consistent, and supported by disclosures rather than arbitrary assumptions."}], "table": {"headers": ["Source", "Primary value", "Main limitation"], "rows": [["Financial statements", "Standardized performance, position, and cash-flow data", "Aggregation and accounting-policy effects"], ["Notes", "Policies, estimates, commitments, segment and risk detail", "Complexity and delayed disclosure"], ["Management commentary", "Strategy, drivers, outlook, nonfinancial indicators", "Potential optimism and selective emphasis"], ["Audit report", "Independent assurance and highlighted judgment areas", "Not a guarantee of future success or fraud-free reporting"], ["External data", "Industry, economy, competitors, market expectations", "May use inconsistent definitions or estimates"]]}, "worked": [{"problem": "A lender is deciding whether to renew a one-year credit facility. Which analysis objective should receive the greatest emphasis?", "solution": ["Define the decision: short-term lending renewal.", "Identify the key risks: liquidity, near-term cash flow, refinancing, collateral, and covenant compliance.", "Prioritize current assets and liabilities, operating cash flow, unused facilities, debt maturities, and stress scenarios."], "answer": "Emphasize near-term liquidity and debt-servicing capacity rather than long-horizon equity valuation."}, {"problem": "Two companies report identical operating profit, but one capitalizes development costs while the other expenses them.", "solution": ["Recognize that capitalization increases current assets and current profit relative to immediate expensing.", "Review notes for policy and amortization details.", "Restate or supplement ratios to place both firms on a more comparable basis."], "answer": "Reported profit is not directly comparable without adjusting for the accounting-policy difference."}], "traps": ["Reading only the face of the statements and ignoring notes.", "Treating audited statements as proof of financial strength.", "Beginning ratio calculations before defining the analytical purpose.", "Using management-defined metrics without reconciling them to reported figures."], "memory": "P-C-P-A-C-F: Purpose, Collect, Process, Analyze, Communicate, Follow up."}, "1": {"title": "Analyzing Income Statements", "summary": "The income statement reports performance over a period. Exam questions often test revenue and expense recognition, capitalization versus expensing, nonrecurring items, earnings per share, common-size analysis, and whether reported earnings are sustainable.", "mustKnow": ["Revenue is recognized when the reporting criteria are satisfied, not necessarily when cash is collected.", "Capitalizing a cost initially raises assets and profit relative to expensing; later amortization or depreciation reduces future profit.", "Nonrecurring items should be evaluated for persistence and classification rather than automatically ignored.", "Basic EPS uses weighted-average common shares. Diluted EPS includes dilutive potential common shares but excludes antidilutive instruments.", "Common-size income statements express each item as a percentage of revenue."], "detailed": [{"heading": "Revenue recognition", "text": "Analyze the timing, amount, uncertainty, contract terms, returns, warranties, and remaining performance obligations. Aggressive recognition can pull future revenue into the current period, increase receivables or contract assets, and weaken cash conversion."}, {"heading": "Expense recognition and capitalization", "text": "Costs that create probable future benefits may be capitalized when the framework permits. Immediate expensing lowers current profit and assets. Capitalization raises current profit but creates future depreciation, amortization, or impairment charges."}, {"heading": "Nonrecurring and unusual items", "text": "Discontinued operations are separately presented when criteria are met. Restructuring, litigation, asset sales, and impairments may be unusual but can recur economically. Normalize earnings only after understanding the business and management’s history."}, {"heading": "EPS", "text": "Basic EPS equals income available to common shareholders divided by weighted-average common shares. Diluted EPS assumes conversion or exercise of dilutive instruments using the applicable method. Antidilutive effects are excluded."}, {"heading": "Margin analysis", "text": "Gross margin reflects pricing, product mix, and input costs. Operating margin also incorporates operating efficiency and cost structure. Net margin includes financing, tax, and nonoperating effects."}], "table": {"headers": ["Choice/event", "Current-period profit", "Assets", "Future expense"], "rows": [["Expense immediately", "Lower", "Lower", "None from the item"], ["Capitalize", "Higher", "Higher", "Depreciation/amortization or impairment"], ["Accelerate revenue", "Higher", "Often higher receivables/contract assets", "May reduce future revenue"], ["Impair asset", "Lower", "Lower", "Lower future depreciation may follow"]]}, "worked": [{"problem": "Net income is 2.4 million, preferred dividends are 0.2 million, and weighted-average common shares are 1.1 million.", "solution": ["Income available to common = 2.4−0.2 = 2.2 million.", "Basic EPS = 2.2/1.1."], "answer": "Basic EPS = 2.00."}, {"problem": "A firm capitalizes 600,000 of eligible costs and amortizes them straight-line over three years. Compare year-one pretax profit with immediate expensing, assuming a full year of amortization.", "solution": ["Immediate expense = 600,000.", "Capitalized amortization = 600,000/3 = 200,000.", "Difference = 400,000."], "answer": "Year-one pretax profit is 400,000 higher under capitalization."}, {"problem": "Revenue is 1,000, COGS 620, operating expenses 230, interest 30, and tax 24.", "solution": ["Gross profit = 380; gross margin = 38%.", "Operating profit = 150; operating margin = 15%.", "Pretax profit = 120; net income = 96; net margin = 9.6%."], "answer": "Gross margin 38%, operating margin 15%, net margin 9.6%."}], "traps": ["Using ending shares instead of weighted-average shares.", "Including antidilutive instruments in diluted EPS.", "Assuming every 'one-time' charge should be removed.", "Confusing cash collection with revenue recognition.", "Ignoring future amortization created by capitalization."], "memory": "Revenue timing, Expense timing, Persistence, EPS, Margins: REPEM."}, "2": {"title": "Analyzing Balance Sheets", "summary": "The balance sheet reports resources, obligations, and owners’ claims at a point in time. Analysis focuses on measurement bases, liquidity, solvency, intangible assets, goodwill, financial instruments, noncurrent liabilities, and common-size relationships.", "mustKnow": ["Assets and liabilities may be measured using historical cost, amortized cost, fair value, or other bases.", "Internally generated intangible assets are often treated differently from purchased intangibles, reducing comparability.", "Goodwill arises in a business combination and is tested for impairment rather than treated as a separable operating asset.", "Financial instruments require attention to classification, measurement, credit losses, and fair-value disclosures.", "Common-size balance sheets express each item as a percentage of total assets."], "detailed": [{"heading": "Intangible assets", "text": "Purchased identifiable intangibles are recognized when criteria are met. Finite-lived intangibles are amortized; indefinite-lived intangibles are tested for impairment. Internally generated brands, customer relationships, and similar resources may be economically important even when not recognized."}, {"heading": "Goodwill", "text": "Goodwill equals the excess of acquisition consideration and relevant recognized interests over the fair value of identifiable net assets under the applicable framework. It is not amortized under IFRS or US GAAP for public-company reporting, but is tested for impairment. Large goodwill balances can signal acquisition dependence."}, {"heading": "Financial instruments", "text": "Measurement depends on the instrument and classification. Analysts should distinguish contractual cash-flow assets, fair-value exposures, derivatives, impairment allowances, and items recognized through profit, OCI, or equity."}, {"heading": "Noncurrent liabilities", "text": "Debt analysis requires coupon, maturity, security, covenants, currency, fixed or floating rates, and off-balance-sheet commitments. The face amount alone does not describe refinancing or interest-rate risk."}, {"heading": "Common-size analysis", "text": "Scaling by total assets makes structure comparable across firms and over time. Interpretation still requires business context; a bank and a manufacturer naturally have different structures."}], "table": {"headers": ["Item", "Key analytical issue", "Possible warning"], "rows": [["Goodwill", "Acquisition assumptions and impairment testing", "Goodwill large relative to equity"], ["Intangibles", "Useful life, amortization, recognition differences", "Frequent impairment or aggressive capitalization"], ["Receivables", "Collectability and revenue quality", "Receivables growing faster than sales"], ["Debt", "Maturity, rates, covenants, currency", "Near-term maturity concentration"], ["Provisions", "Estimate uncertainty and timing", "Repeated reversals or weak disclosure"]]}, "worked": [{"problem": "Total assets are 500, inventory is 75, receivables 100, PPE 180, and goodwill 60. Calculate selected common-size percentages.", "solution": ["Inventory: 75/500 = 15%.", "Receivables: 100/500 = 20%.", "PPE: 180/500 = 36%.", "Goodwill: 60/500 = 12%."], "answer": "15%, 20%, 36%, and 12%, respectively."}, {"problem": "A company acquires a target for 300. Fair value of identifiable assets is 360 and liabilities 110.", "solution": ["Identifiable net assets = 360−110 = 250.", "Goodwill = 300−250."], "answer": "Goodwill = 50."}, {"problem": "Current assets are 240, inventory 80, and current liabilities 160.", "solution": ["Current ratio = 240/160 = 1.50.", "Quick ratio = (240−80)/160 = 1.00."], "answer": "Current ratio 1.50; quick ratio 1.00."}], "traps": ["Treating book value as market value.", "Assuming unrecognized internally generated intangibles have no economic value.", "Ignoring maturity schedules and covenant disclosures.", "Comparing common-size balances across unrelated business models without context."], "memory": "I-G-F-L-C: Intangibles, Goodwill, Financial instruments, Liabilities, Common size."}, "3": {"title": "Analyzing Statements of Cash Flows I", "summary": "The cash-flow statement reconciles beginning and ending cash by classifying cash flows as operating, investing, or financing. The direct and indirect methods differ only in presenting operating cash flow; total operating cash flow is the same when correctly prepared.", "mustKnow": ["Operating cash flow generally relates to core operations and working capital.", "Investing cash flow generally includes acquisition and disposal of long-term assets and investments.", "Financing cash flow generally includes transactions with debt and equity capital providers.", "The indirect method begins with net income and adjusts for noncash items, nonoperating items, and working-capital changes.", "IFRS and US GAAP differ in permitted classification of interest and dividends."], "detailed": [{"heading": "Link between statements", "text": "Cash changes arise from transactions recorded across the income statement and balance sheet. For example, credit sales increase revenue and receivables without immediate cash. Buying equipment uses investing cash while creating a balance-sheet asset."}, {"heading": "Indirect operating cash flow", "text": "Start with net income. Add back noncash expenses such as depreciation. Remove gains and losses whose cash effects belong in investing or financing. Subtract increases in operating assets and add increases in operating liabilities."}, {"heading": "Direct operating cash flow", "text": "The direct method reports major cash receipts and payments, such as cash collected from customers, cash paid to suppliers and employees, and taxes paid. It provides intuitive information about operating cash sources and uses."}, {"heading": "Classification differences", "text": "Under US GAAP, interest paid and received are operating; dividends received are operating; dividends paid are financing. IFRS allows specified policy choices for interest and dividends, applied consistently. Always use the classification stated or required by the question."}], "table": {"headers": ["Change", "Indirect CFO adjustment"], "rows": [["Operating asset increases", "Subtract"], ["Operating asset decreases", "Add"], ["Operating liability increases", "Add"], ["Operating liability decreases", "Subtract"], ["Noncash expense", "Add back"], ["Gain included in net income", "Subtract"], ["Loss included in net income", "Add"]]}, "worked": [{"problem": "Net income 150; depreciation 25; gain on equipment sale 8; receivables increase 12; inventory decreases 5; payables decrease 7.", "solution": ["Start 150.", "Add depreciation +25.", "Subtract gain −8.", "Subtract receivable increase −12.", "Add inventory decrease +5.", "Subtract payable decrease −7."], "answer": "CFO = 153."}, {"problem": "Sales are 900. Receivables increase from 70 to 95. Calculate cash collected from customers, assuming no other relevant items.", "solution": ["Increase in receivables = 25.", "Cash collected = sales−increase in receivables.", "900−25."], "answer": "Cash collected = 875."}, {"problem": "COGS is 500, inventory rises by 30, and payables rise by 20. Estimate cash paid to suppliers.", "solution": ["Purchases = COGS + increase in inventory = 530.", "Cash paid = purchases − increase in payables = 510."], "answer": "Cash paid to suppliers = 510."}], "traps": ["Reversing working-capital signs.", "Leaving a gain in CFO while also showing sale proceeds in investing cash flow.", "Assuming direct and indirect methods produce different CFO totals.", "Applying IFRS classification choices as if they were mandatory."], "memory": "Assets opposite; liabilities same: asset increase subtracts, liability increase adds."}, "4": {"title": "Analyzing Statements of Cash Flows II", "summary": "Cash-flow analysis evaluates the quality, sustainability, and allocation of cash. Analysts use common-size statements, free cash flow, coverage ratios, and comparisons between earnings and operating cash flow to assess financial flexibility.", "mustKnow": ["Common-size cash-flow statements can scale items by revenue or total inflows/outflows to reveal structural changes.", "FCFF is cash available to all capital providers after operating expenses, taxes, and required investment.", "FCFE is cash available to common equity after investment and net borrowing.", "Persistent divergence between net income and CFO requires explanation.", "Coverage ratios connect cash generation with interest, debt, or capital expenditure commitments."], "detailed": [{"heading": "Cash-flow quality", "text": "High-quality earnings are generally supported by cash, but temporary working-capital movements can create legitimate differences. Analyze multi-period trends, business seasonality, growth investment, and classification choices before concluding that earnings quality is weak."}, {"heading": "FCFF and FCFE", "text": "A common starting formulation is FCFF = CFO + after-tax interest − capital expenditure when interest paid is included in CFO. FCFE = CFO − capital expenditure + net borrowing. Exact formulations depend on the starting data and classification."}, {"heading": "Coverage and performance ratios", "text": "Operating cash flow to debt, cash interest coverage, and CFO margin help evaluate debt capacity and cash profitability. Definitions may vary, so state the numerator and denominator and use them consistently."}, {"heading": "Common-size analysis", "text": "Expressing CFO, capital expenditure, and financing flows as percentages of revenue can reveal whether growth is becoming more cash intensive, whether debt funds distributions, or whether operating cash supports investment."}], "table": {"headers": ["Metric", "Illustrative formula", "Interpretation"], "rows": [["CFO margin", "CFO/revenue", "Cash generated per unit of revenue"], ["CFO to debt", "CFO/average or ending debt", "Cash debt-servicing capacity"], ["FCFF", "CFO + after-tax interest − capex", "Cash available to debt and equity"], ["FCFE", "CFO − capex + net borrowing", "Cash available to common equity"], ["Cash reinvestment", "Capex/CFO", "Share of operating cash reinvested"]]}, "worked": [{"problem": "CFO is 220, interest paid 30, tax rate 25%, and capital expenditure 90. Interest paid is classified in CFO.", "solution": ["After-tax interest = 30×(1−0.25)=22.5.", "FCFF = 220+22.5−90."], "answer": "FCFF = 152.5."}, {"problem": "CFO is 220, capex 90, debt issued 50, and debt repaid 20.", "solution": ["Net borrowing = 50−20 = 30.", "FCFE = 220−90+30."], "answer": "FCFE = 160."}, {"problem": "Revenue is 1,100, CFO 165, and total debt 600.", "solution": ["CFO margin = 165/1,100 = 15%.", "CFO-to-debt = 165/600 = 27.5%."], "answer": "CFO margin 15%; CFO-to-debt 27.5%."}], "traps": ["Adding full interest rather than after-tax interest when deriving FCFF from CFO.", "Using debt issuance instead of net borrowing for FCFE.", "Calling all negative investing cash flow bad; productive capex may support growth.", "Using one-year CFO without considering seasonality and working-capital cycles."], "memory": "FCFF serves Firm; FCFE serves Equity."}}};